    val seq: IndexedSeq[Long] = {for (i <- 1 to n) yield scala.io.StdIn.readLong()}
    val (retSeq, g, cnt) = seq.shellSort()

    println(g.length)
    println(g.mkString(" "))
    println(cnt)
    retSeq.foreach(println)
  }

  implicit class RichSeqLong(seq: Seq[Long]) {
    def insertionSort(prevCnt: Long, n: Int, g: Int): (Seq[Long], Long) = {
      (g until n).foldLeft((seq, prevCnt)) { (t, i) => t._1.swapEachG(t._2, i, g) }
    }

    def swapEachG(prevCnt: Long, i: Int, g: Int): (Seq[Long], Long) = {

      val v = seq(i)
      val jSeq = {for (j <- i - g to 0 by -g) yield j}.takeWhile(j => seq(j) > v)

      if (jSeq.isEmpty) return (seq, prevCnt)

      val (retSeq, cnt): (Seq[Long], Long) =
        jSeq.foldLeft((seq, 0l)) { (t, j) => (t._1.updated(j + g, t._1(j)), t._2 + 1) }

      (retSeq.updated(jSeq.last, v), cnt + prevCnt)
    }

    def recuresiveLoop(G: Seq[Int], n: Int): (Seq[Long], Long) = {
      G.foldLeft((seq, 0l)) { (t, g) => t._1.insertionSort(t._2, n, g) }
    }

    implicit class RichObj[T](obj: T) {
      def tap[U](f: T => U): T = {
        f(obj);
        obj;
      }
    }

    def shellSort(): (Seq[Long], Seq[Int], Long) = {
      val n = seq.length

      def genG(n: Long): Stream[Long] = Stream.cons(n, genG(3 * n + 1))

      val G: Seq[Int] = genG(1)
                        .takeWhile(_ <= n)
                        .map(_.asInstanceOf[Int])
                        .toList
                        .reverse

      val (retSeq, cnt) = seq.recuresiveLoop(G, n)

      (retSeq, G, cnt)
    }
  }

}

import scala.io.StdIn.{readLong, readInt}
object Main {
    def main(args: Array[String]): Unit = {
        val len = readInt
        val arr = (1 to len).toArray.map(a => readLong)
        println(shellSort(arr, len).mkString("\n"))
    }

    def shellSort(arr: Array[Long], len: Int): Array[Long] = {
        val copy = new Array[Long](len)
        arr.copyToArray(copy)
        var cnt = 0
        val groups = genGroups(len).reverse
        println(groups.length + "\n" + groups.mkString(" "))
        for (g <- groups) {
            cnt += insertionSort(copy, len, g)
        } 
        println(cnt)
        copy
    }

    def insertionSort(arr: Array[Long], len: Int, group: Int): Int = {
        var cnt = 0
        def insert(target: Long, ptr: Int): Unit = ptr match {
            case a if (a < 0 || arr(ptr) <= target) => arr(ptr + group) = target
            case a => {
                cnt += 1
                arr(ptr + group) = arr(ptr)
                insert(target, ptr - group)
            }
        }
        for (targetIndex <- (0 until len)) { insert(arr(targetIndex), targetIndex - group)}
        cnt
    }

    def genGroups(len: Int): List[Int] =  {
        def go(len: Int, glen: Int, next: Int): List[Int] = next match {
            case a if (a == 1) || (a < len && glen < len) => a :: go(len, glen + 1, a * 3 + 1)
            case a => Nil
        }
        go(len, 0, 1)
    }
}

