        std::cout << "----------" << std::endl;
        std::cout << "Invalid gap is inputted." << std::endl;
        std::cout << gap << std::endl;
        std::cout << "----------" << std::endl;
    }
    long int n = ary.size();
    for (long int i=gap; i<n; i++) {
        long int temp = ary[i];
        long int j = i - gap;
        while(j>=0 && ary[j] > temp) {
            ary[j+gap] = ary[j];
            cnt++;
            j -= gap;
        }
        ary[j+gap] = temp;
    }
    return std::tuple<std::vector<long int>, long int>(ary, cnt);
}

