int insertion_sort(int n, int g)
{
	int cnt = 0;
	for (int i = g; i < n; i++) {
		int key = elements[i],
			j = i - g;
		while (key < elements[j] && 0 <= j) {
			elements[j + g] = elements[j];
			j -= g;
			cnt++;
		}
		elements[j + g] = key;
	}
	return cnt;
}

void shell_sort(int n)
{
	int cnt = 0, m = 0, g[13] = { 1, 4, 13, 40, 121, 364, 1093, 3280, 9841, 29524, 88573, 265720, 797161 };

