int forgetind(int i, int x){
	int S = 1;
	int result = 0;

	while (S <= x){
		S *= i;
		result += 1;
	}
	return result - 1;
}

int power(int x, int i){
	int result = 1;
	for (int j = 0; j < i; j ++){
		result *= x;
	}
	return result;
}

