void INSERT(int* A, int n, int g, int* cnt) {
    for(int i = g; i < n; ++i) {
        int tmp = A[i];
        int j = i - g;
        while(-1 < j && tmp < A[j]) {
            A[j + g] = A[j];
            j = j - g;
            ++*cnt;
        }
        A[j + g] = tmp;
    }
}

void SHELL(int* A, int n) {
    int cnt = 0;
    int m;
    int G[100];
    for(int i = 0; i < 100; ++i) {
        if(i == 0) {
            G[i] = n / 2 + 1;
        } else {
            G[i] = G[i - 1] / 2 - 1;
        }
        if(G[i] < 0) {
            G[i - 1] = 1;
            G[i] = 0;
            m = i;
            break;
        }
    }
    for(int i = 0; i < m; ++i) {
        INSERT(A, n, G[i], &cnt);
    }

    cout << m << endl;
    for(int i = 0; i < m; ++i) {
        if(i)   cout << ' ';
        cout << G[i];
    }
    cout << endl;
    cout << cnt << endl;
    for(int i = 0; i < n; ++i) {
        cout << A[i] << endl;
    }
}

