int insertionSort(int N, int V[], int g, int cnt) {
	int v, j;
	for (int i = g; i < N; i++) {
		v = V[i];
		j = i - g;
		while (j >= 0 && V[j] > v) {
			V[j + g] = V[j];
			j = j - g;
			cnt++;
		}
		V[j + g] = v;
	}

	return cnt;
}

int shellSort(int N, int V[]) {

	int G[NMAX], m = 1, cnt = 0;

