	template<typename T>
	void PrintLine(const std::vector<T>& sequence)
	{
		std::cout << sequence[0];

		for (size_t i = 1; i < sequence.size(); ++i)
		{
			std::cout << ' ' << sequence[i];
		}

		std::cout << std::endl;
	}

	template<typename T>
	void Print(const std::vector<T>& sequence)
	{
		for (const auto& e : sequence)
		{
			std::cout << e << '\n';
		}

		std::cout << std::flush;
	}

	int gCount = 0;

	void InsertionSort(std::vector<int>& sequence, int step)
	{
		for (size_t i = step; i < sequence.size(); ++i)
		{
			int v = sequence[i];
			int j = i - step;

			while (0 <= j && v < sequence[j])
			{
				sequence[j + step] = sequence[j];
				j -= step;
				++gCount;
			}

			sequence[j + step] = v;
		}
	}

	void ShellSort(std::vector<int>& sequence)
	{
		std::vector<int> ar = { 1 };
		while (true)
		{
			size_t t = ar.back() * 3 + 1;

			if (sequence.size() <= t)
			{
				break;
			}

			ar.push_back(t);
		}
		std::reverse(ar.begin(), ar.end());

		for (int e : ar)
		{
			InsertionSort(sequence, e);
		}

		std::cout << ar.size() << '\n';
		PrintLine(ar);
		std::cout << gCount << '\n';

	}
}

