#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

unsigned int	cnt	{0};

void	insertionSort(std::vector<unsigned int>&	A,
					  unsigned int					n,
					  unsigned int					g)
{
	for(unsigned int i = g; i < n; i++){
		auto	v	= A[i];
		int		j	= i - g;
		while((j >= 0) && (A[j] > v)){
			A[j + g]	= A[j];
			j			= j - g;
			cnt++;
		}
		A[j + g]	= v;
	}
}

void	shellSort(std::vector<unsigned int>&	A,
				  unsigned int					n)
{
	cnt	= 0;

	unsigned int				m	{0};
	unsigned int				g	{0};
	std::vector<unsigned int>	G	{};

	// 1, 4, 13, 40, 121, ...の数列{an}を作る
	// anは階差数列なので差をとると
	// 3, 9, 27, 81, ... と、初項3、公比3の等比数列となっている。これを{bn}とすると
	// bn = 3 * 3^(n - 1) = 3^n
	// よって、階差数列の公式より
	// an = a1 + Σ[k=1, n - 1]3^k
	//    = 1 + {3 * (1 - 3^(n - 1)) / (1 - 3)}
	//    = 1 + {(3 ^ n - 3) / 2}
	//    = (3 ^ n - 1) / 2
	// となる
	for(unsigned int i = 0; i < n; i++){
		g	= (static_cast<unsigned int>(std::pow(3, (i + 1)) - 1)) / 2;
		if(g > n){
			break;
		}
		G.push_back(g);
		m++;
	}

	// 逆行列にする
	std::reverse(G.begin(), G.end());

	std::cout << m << std::endl;

	for(auto i = 0; i < m; i++){
		std::cout << G[i];
		if(i == (m - 1)){
			std::cout << std::endl;
		}
		else{
			std::cout << ' ';
		}
		insertionSort(A, n, G[i]);
	}
}

