		 char*	argv[])
{
	unsigned int				N	{0};
	std::vector<unsigned int>	A	{};

	std::cin >> N;

	for(unsigned int i = 0; i < N; i++){
		unsigned int	element	{0};
		std::cin >> element;
		A.push_back(element);
	}

	shellSort(A, N);

	std::cout << cnt << std::endl;

	for(unsigned int i = 0; i < N; i++){
		std::cout << A[i] << std::endl;
	}

    return 0;
}

