		std::cout << std::fixed << std::setprecision(digit) << d;
	}
	template <typename T>
	void operator()(T t) {
		std::cout << t;
	}
	template <typename T>
	void operator()(const std::vector<T> &v, const std::string &sep = " ") {
		if (v.empty()) return;
		Print()(v[0]);
		for(int i = 1;  i < v.size(); ++i) {
			Print()(sep);
			Print()(v[i]);
		}
		return;
	}
	template <typename T>
	void operator()(T begin, T end, const std::string &sep = " ") {
		if (begin == end) return;
		Print()(*begin);
		for(auto it = ++begin;  it != end; ++it) {
			Print()(sep);
			Print()(*it);
		}
		return;
	}
}print;
struct Println {
	void operator()(void) {
		std::cout << std::endl;
	}
	void operator()(double d, int digit) {
		print(d, digit);
		Println()();
	}
	template <typename T>
	void operator()(T t) {
		print(t);
		Println()();
	}
	template <typename T>
	void operator()(const std::vector<T> &v, const std::string &sep = " ") {
		print(v, sep);
		Println()();
	}
	template <typename T>
	void operator()(T begin, T end, const std::string &sep = " ") {
		print(begin, end, sep);
		Println()();
		return;
	}
}println;

long long InsertSort(vector<long long> *vec, int g) {
	vector<long long> &v = *vec;
	auto count = 0;
	for (long long i = g; i < v.size(); ++i) {
		auto pivod = v[i];
		auto j = i - g;
		while(j >= 0 && v[j] > pivod) {
			v[j + g] = v[j];
			j -= g;
			count++;
		}
		v[j + g] = pivod;
	}
	return count;
}

long long ShellSort(vector<long long> *vec) {
	vector<long long> &v = *vec;
	auto count = 0;
	vector<long long> G;
	for(auto i = 1; i <= v.size(); i = i * 3 + 1) {
		G.push_back(i);
	}
	for(auto it = G.rbegin(); it != G.rend(); ++it) {
		count += InsertSort(&v, *it);
	}
	println(G.size());
	println(G.crbegin(), G.crend());
	return count;
}

int main(void){
	cin.tie(0);
	ios::sync_with_stdio(false);

	auto size = read();
