{
    int cnt = 0;
    int m = (int)(n / 2);
    if( 100 < m ) m = 100;
    int G[m];
    for( int i = 0; i < m; ++i ){
	if( i < 1 ) G[i] = n - 1;
	else if( i == m-1 ) G[i] = 1;
	else G[i] = G[i-1] / 2 - 1;
    }

    for( int i = 0; i < m; ++i )
	insertionSort(A, n, G[i], &cnt);

    //出力
    printf("%d\n", m);
