void insertionSort(vector<int>& A, int g)
{
    for (int i = g; i < A.size(); ++i)
    {
        if (A[i - g] > A[i])
        {
            int v = A[i];
            int j = i - g;
            while (j >= 0 && A[j] > v)
            {
                A[j + g] = A[j];
                j -= g;
                ++cnt;
            }
            A[j + g] = v;
        }
    }
}

