{
	//初始化间隔序列 
	for(int h=1;h<=n;)
	{
		G.push_back(h); 
		h=3*h+1;
	}
	//倒叙 循环 进行插入排序
	for(int i=G.size()-1;i>=0;--i)
	{
		insertionSort(A,n,G[i]);

	 } 

}

