int insertionSort(int A[],int N,int g){
	int tmp;
	int j;
	int cnt=0;//要素の移動回数
	for(int i=g;i<N;i++){
		tmp = A[i];
		j = i -g;
		while(j >= 0 && A[j] > tmp){
			A[j+g] = A[j];
			j = j-g;
			cnt++;
		}
		A[j+g] = tmp;
	}
	return cnt;
}
