long insertionSort(long A[], long n, long g) {
	long cnt = 0;
	for (long i = g; i < n; ++i) {
		long v = A[i];
		long j = i - g;
		while (j >= 0 && A[j] > v) {
			A[j + g] = A[j];
			j -= g;
			++cnt;
		}
		A[j + g] = v;
	}
	return cnt;
}

long shellSort(long A[], long n) {
	long *G = new long[n];
	long m = 0;
	for (long s = (n > 4) ? 4 : n - 1;
			s > 0; s /= 4, ++m) {
		G[m] = s;
	}

	cout << m << endl;
	p(G, m);

	long cnt = 0;
	for (long i = 0; i < m; ++i)
		cnt += insertionSort(A, n, G[i]);

	delete[] G;
	return cnt;
}

