int InsertionSort(vector<int> &A, int g){
    int N = A.size();
    int cnt = 0;
    for(int i = 0; i < N; ++i){
        int minj = i;
        int flag = 0;
        int j = i;
        while(j < N && flag == 0){
            if(A[j] < A[minj]){
                minj = j;
                flag = 1;
            }
            j += g;
        }
        if(flag){
            int tmp = A[i];
            A[i] = A[minj];
            A[minj] = tmp;
            ++cnt;
        }
    }
    return cnt;
}

int ShellSort(vector<int> &A){
    int N = A.size();
    int cnt = 0;
    vector<int> G;
    int g = 1;
    while(g < N){
        G.push_back(g);
        g = 3 * g + 1;
    }
    for(int i = G.size() - 1; i >= 0; --i){
        cnt += InsertionSort(A, G[i]);
    }
    return cnt;
}

