void makeG(int *array, int M)
{
	for (int i = 0; i < M; ++i)
	{
		if (i == 0)
		{
			array[M - 1 - i] = 1;
		}
		else
		{
			array[M - 1 - i] = 3 * array[M - i] + 1;
		}
	}
}

