int insertionSort(vector<int> &vec,int size,int gap){
  int comp,j,count=0;
  for(int i=gap;i<size;i++){
    comp=vec.at(i);
    j=i-gap;
    while(j>=0&&vec.at(j)>comp){
      vec.at(j+gap)=vec.at(j);
      j=j-gap;
      count++;
    }
    vec.at(j+gap)=comp;
  }
  return count;
}

int shellSort(vector<int> &vec,int size){
  if(size==1) return 0;
  int count=0,loop=0;
  int sizeloop=size;
  vector<int> gap;
  while((sizeloop/2)>0){
    sizeloop/=2;
    loop++;
    gap.push_back(sizeloop);
  }
  for(int i=0;i<loop;i++){
    count+=insertionSort(vec,size,gap.at(i));
  }
  return count;
}

