    while( max <= n )
    {
        max = max * 3 + 1;
        m++;
    }

    if( n < 4 )
    {
        max = 1 * 3 + 1;
        m = 1;
    }

    int G[m];

    cout << m << endl;                          //m個の整数の出力(1行目)

