int
findInsertionPoint(int* array, int num, int target, int g)
{
    int point = 0;
    int i = num;

    while (i >= 0) {
        if (target > array[i]) {
            point = i+g;
            break;
        }
        i = i-g;
    }

    return point;
}

int
insertionSort(int* array, int num, int g)
{
    int cnt = 0;

    for (int i = g; i < num; i=i+g) {
        int target = array[i];
        int point  = findInsertionPoint(array, i-g, target, g);
        for (int j = i; j > point; j=j-g) {
            array[j] = array[j-g];
            gCnt++;
        }
        array[point] = target;
    }


    return cnt;
}

