int InsertionSort(int A[], int n, int g) {
	int i, v, j, cnt = 0;
	for (i = g; i < n; i++) {
		v = A[i]; j = i - g;
		while (j >= 0 && A[j] > v) {
			A[j + g] = A[j]; j = j - g; cnt++;
		}
		A[j + g] = v;
	}
	return cnt;
}

int dev3(int N) {
	int i = 1;
	while (i < N) {
		if (3 * i + 1 > N)break;
		i = 3 * i + 1;
	}
	return i;
}

