// 挿入ソート
void Aoj_learning8sub(int input, int G, int *A, int* cnt)
{
	int v1;
	int j = 0;
	// 数列をソートする
	for (int i = G; i < input; i++)
	{
		v1 = A[i];
		j = i - G;
		while(j >= 0 && A[j] > v1)
		{
			A[j + G] = A[j];
			j = j - G;
			*cnt = *cnt + 1;
		}
		A[j + G] = v1;
	}
}

