int A[1000000];
int n;
vector<int>G;
//間隔Gを指定した挿入ソート
void insertSort(int A[], int n, int g) {
	for (int i = g;i < n;i++) {
		int v = A[i];
		int j = i - g;
		while (j >= 0 && A[j] > v) {
			A[j + g] = A[j];
			j -= g;
			cnt++;
		}
		A[j + g] = v;
	}
}

void ShellSort(int A[], int n) {
	//数列G={1,4,13,40,121,364,1093,...}を生成
	for (int h = 1; ;) {
		if (h > n)break;
		G.push_back(h);
		h = 3 * h + 1;
	}
	for (int i = G.size() - 1;i >= 0;i--) {//逆順にG[i]=gを指定
		insertSort(A, n,G[i]);
	}
}

int main() {
	cin >> n;
	//より速い入力scanf関数を使用
	for (int i = 0;i < n;i++)scanf("%d", &A[i]);
	cnt = 0;

	ShellSort(A, n);

	cout << G.size() << endl;
	for (int i = G.size() - 1;i >= 0;i--) {
		printf("%d", G[i]);
		if (i)printf(" ");
	}
	printf("\n");
	printf("%d\n", cnt);
	for (int i = 0;i < n;i++)printf("%d\n", A[i]);

	return 0;
}

