int insertion_sort(int n, int elements[], int g)
{
	int cnt = 0;
	for (int i = g; i < n; i++) {
		int key = elements[i],
			j = i - g;
		while (key < elements[j] && 0 <= j) {
			elements[j + g] = elements[j];
			j -= g;
			cnt++;
//			output_debug(n, elements);
		}
		elements[j + g] = key;
	}
	return cnt;
}

void shell_sort(int n, int elements[])
{
	int cnt = 0, m = 0, g[100];

	for (int g_calc = 1; g_calc < n; g_calc = g_calc * 3 + 1) {
		g[m] = g_calc;
		m++;
	}
	cout << m << endl;
	for (int i = m - 1; 0 <= i; i--) {
		cout << g[i] << (i == 0 ? "" :  " ");
		cnt += insertion_sort(n, elements, g[i]);
	}
	cout << endl;
	cout << cnt << endl;
}

int main()
{
	int n;

	// input
	cin >> n;
	for (int i = 0; i < n; i++)
		cin >> elements[i];

	// sort
	shell_sort(n, elements);
	output(n, elements);
	return 0;
}

