            j -= g;
            cnt++;
        }
        a[j+g]=v;
    }
}
void shellSort(vector<int> &a,const vector<int> &g)
{
    for(unsigned int i=0;i<g.size();i++)
        insertSort(a,g[i]);
    return ;
}
