#include<iostream>
#include<vector>
using namespace std;

const int N = 1000000;

void insertion_sort(int n, int g, int &cnt, int A[]) {
  int i, j, v;

  for (i = g; i < n; i++) {
    v = A[i];
    for (j = i - g; j >= 0; j -= g) {
      if (A[j] > v) {
        A[j+g] = A[j];
        cnt++;
      } else {
        break;
      }
    }
    A[j+g] = v;
  }
}

int shell_sort(int n, int A[], vector<int> G) {
  int cnt = 0, m;

  m = G.size();
  for (int i = m - 1; i >= 0; i--) {
    insertion_sort(n, G[i], cnt, A);
  }

  return cnt;
}

int main() {
  int i, n;
  int A[N];
  vector<int> G;

  cin >> n;
  for (i = 0; i < n; i++) cin >> A[i];

  int g = 1;  
  while (g <= n) {
    G.push_back(g);
    g = 3 * g + 1;
  }

  int cnt = shell_sort(n, A, G);

  // output
  int m = G.size();
  cout << m << endl;

  for (i = m-1; i >= 0; i--) {
    if (i < m - 1) cout << " ";
    cout << G[i];
  }
  cout << endl;

  cout << cnt << endl;

  for (i = 0; i < n; i++) cout << A[i] << endl;

  return 0;
}

