	vector<int> va;
	for (int i = 0; i < n; ++i) {
		int t;
		cin >> t;
		va.push_back(t);
	}

	cShell cs(n, va);
	cs.shellSort();

	cout << cs.getm() << endl;
	cout << cs.getGapToStr() << endl;
	cout << cs.getCnt() << endl;
	va = cs.getData();
	for (int i = 0; i < va.size(); ++i)
	{
		cout << va[i] << endl;
	}

	return 0;
}

