// シェルソートを実施する関数
void shellSort(int A[], int n)
{
    // 挿入ソートを実施する間隔
    // 数列 : G = {1, 4, 13, 40, 121, 364,・・・・}を生成
    for(int h = 1 ; ;)
    {
        if( h > n )
        {
            break;
        }

        G.push_back(h);
        h = ( 3 * h ) + 1;
    }

    for(int i = G.size() - 1; i >= 0; i--)
    {
        // 逆順にG[i] = gを指定
        insertionSort(&A[0], n, G[i]);
    }

    return;
}

// 挿入ソートを実施する関数
// g : 挿入ソートを実施する間隔
void insertionSort(int A[], int n, int g)
{
    int v, j;

    for(int i = g; i < n; i++)
    {
        // 挿入する値をラッチする
        v = A[i];
        // 比較対象の要素No.を設定する
        j = i - g;

        while( j >= 0 && A[j] > v )
        {
            // vよりも値が大きいは後ろにコピーして、前の要素へ戻る
            A[j + g] = A[j];
            j = j - g;

            // 交換回数のカウント
            cnt++;
        }

        // 値のソートで、値を入れるべき所に値を入れる
        A[j + g] = v;

    }

    return;
}

