void insertionSort(vector<int>& vec, int g)
{
  for(int i=g; i<vec.size(); i++) {
    int v = vec[i];
    int j = i-g;
    while(j >= 0 && vec[j] > v) {
      vec[(j+g)%m] = vec[j];
      j = j - g;
      cnt ++;
    }
    vec[(j+g)%m] = v;
  }
}

void shellSort(vector<int>& vec)
{
  cnt = 0;
  m = vec.size();
  G.clear(); G.resize(m);
  for(int i=0; i<m-1; i++) G[i] = m-i-1;
  for(int i=0; i<m; i++) insertionSort(vec, G[i]);
}

