using namespace std;

int insertSort(vector<int>& arr, int step) {
  int cnt = 0;
  for (auto i = step; i < arr.size(); ++i) {
    auto j = i - step;
    auto v = arr[i];
    for (; j >= 0 && arr[j] > v; j -= step) {
      arr[j + step] = arr[j];
      ++cnt;
    }
    arr[j + step] = v;
  }
  return cnt;
}

vector<int> makeSteps(int n) {
  vector<int> steps;
  for (int v = 1; v < n; v *= 4) {
    steps.push_back(v);
  }
  sort(steps.begin(), steps.end(), greater<int>()); 
  return steps;
}

