int insertion_sort(int_vec& v, int g) {
    int count = 0;
    for (int i = g; i < v.size(); ++i) {
        int x = v[i];
        int j = i - g;
        for (; j >= 0 && v[j] > x; j -= g) {
            v[j+g] = v[j];
            ++count;
        }
        v[j+g] = x;
    }
    return count;
}

int shell_sort(int_vec& v) {
    int m = min(static_cast<int>((v.size() - 1) / 3) + 1, 100);
    int_vec G;
    for (int i = 0; i < m; ++i) {
        auto g = 3 * i + 1;
        G.push_back(g);
    }
    reverse(G.begin(), G.end());
    cout << G.size() << endl;
    if (G.size() > 0)
        print(G);

    int count = 0;
    for (auto it = G.begin(); it != G.end(); ++it) {
        count += insertion_sort(v, *it);
    }
    return count;
}

