void getGarray(int arraySize, int *&pG, int &gSize) {
	int i = 1;
	stack<int> s;
	while (i <= arraySize) {
		s.push(i);
		i *= 2;
	}
	gSize = s.size();
	pG = new int[gSize];
	for (int i = 0; i < gSize; i++) {
		pG[i] = s.top();
		s.pop();
	}
