void shell_sort(unsigned a[], unsigned n){
  const unsigned gaps[] = {1,8,23,77,281,1073,4193,16577,65921,262913,1050113};
  // pow(4,i)+3*pow(2,i-1)+1 (prefixed with 1)

  unsigned gap_num = 11, count = 0;
  while(gaps[--gap_num] > n);

  for(int i = gap_num+1; i; i--){
    unsigned gap = gaps[i-1];
    for(unsigned j = gap; j < n; j++){
      unsigned v = a[j];
      int k = j - gap;
      while(k >= 0 && a[k] > v){
        a[k+gap] = a[k];
        k -= gap;
        count++;
      }
      a[k+gap] = v;
    }
  }

  cout << (gap_num+1) << '\n';

  for(; gap_num; gap_num--) cout << gaps[gap_num] << ' ';
  cout << gaps[0] << '\n';

  cout << count << '\n';
}

