    for (int i = 0; i < n - 1; i++) {
        if (A[i] > A[i + 1]) {
            return false;
        }
    }
    return true;
}

void shellSort(int* A, int n)
{
    int m = 1;
    for (int i = n; i > 1; i = i / 3) {
        m++;
    }
    int* G = (int*)calloc(m, sizeof(int));
    while (1) {
        for (int i = 0; i < m; i++) {
            if (i != 0) {
                G[m - 1 - i] = 1 + G[m - i] * 3;
            } else {
                G[m - 1] = 1;
            }
        }
        for (int i = 0; i < m; i++) {
            insertionSort(A, n, G[i]);
            if (sorted(A, n)) {
                break;
            }
        }
        if (sorted(A, n)) {
            break;
        }
    }

    //m
    std::cout << m << std::endl;
    //G[i]
    for (int i = 0; i < m; i++) {
        std::cout << G[i];
        if (i != m - 1) {
            std::cout << " ";
        } else {
            std::cout << std::endl;
        }
    }
    //cnt
    std::cout << cnt << std::endl;
    //A[i]
    for (int i = 0; i < n; i++) {
        std::cout << A[i] << std::endl;
        ;
    }
}

