int InsertionSort(int *A, int N, int g)
{
	int cnt = 0;

	int i,j,v;

	for ( i = g; i < N; ++i)
	{
		v = A[i];
		for (j = i - g; j > -1 && A[j] > v; j -= g) 
		{
			A[j + g] = A[j];
			++cnt;
		}

		A[j + g] = v;
	}

	return cnt;
}

void ShellSort(int *A, int N)
{
	int cnt = 0;
	vector<int> G;
	int g = 1;
	while (g < N)
	{
		G.push_back(g);
		g = 3 * g + 1;
	}
	int m = G.size();

	for (int i = m - 1; i >= 0; --i)
	{
		cnt += InsertionSort(A, N, G[i]);
