      A[j+g] = A[j];
      j = j - g;
      cnt++;
    }
    A[j+g] = v;
  }
}

void shellSort(){
  cnt = 0;
  int m = rand() % min(n,100) + 1;
  int *G = new int[m];
  G[0] = 1;
  set<int> used;
  used.insert(1);
  REP(i,1,m){
    int v = rand() % n + 1;
    while( used.find(v) != used.end() ) v = rand() % ( n + 1 );
    used.insert(v);
    G[i] = v;
  }
  sort(G,G+m);
  for(int i=m-1;i>=0;i--)insertionSort(G[i]);
  cout << m << endl;
  for(int i=m-1;i>=0;i--){
    if( i != m-1 ) cout << ' '; 
    cout << G[i];
  } cout << endl;
  cout << cnt << endl;
  rep(i,n)cout << A[i] << endl;
  delete [] G;
}

