std::vector<int> insertionSort(std::vector<int> ls, int n, int g) {
	int v, j;
	for (int i = g; i < n; i++) {
		v = ls[i];
		j = i - g;
		while (j >= 0 && ls[j] > v) {
			ls[j + g] = ls[j];
			j = j - g;
			cnt++;
		}
		ls[j + g] = v;
	}
	return ls;
}

void shellSort(std::vector<int> ls, int n) {
	cnt = 0;
	int m;
	if (n == 1) {
		m = 1;
	}
	else {
		m = log(n) / log(2);
	}

	std::vector<int> G(m);
	for (int i = 0, j = m; i < m; i++, j--) {
		if (i == m - 1) {
			G[i] = 1;
		}
		else {
			G[i] = pow(2, j);
		}
	}

	for (int i = 0; i < m; i++) {
		ls = insertionSort(ls, n, G[i]);
	}
	std::cout << m << "\n";

	for (int i = 0; i < m - 1; i++) {
		std::cout << G[i] << " ";
	}
	std::cout << G[m - 1] << "\n";
	std::cout << cnt << "\n";
	for (int i = 0; i < n; i++) {
		std::cout << ls[i] << "\n";
	}
}

