    j=i-g;
    v = A[i];
    while(1){
      if(A[j] < v){
        for(int k=i; k>=j+g; k-=g){
          count++;
          A[k] = A[k-g];
        }
        A[j+g] = v;
        break;
      }
      j -=g;
      if(j<0){
        for(int k=i; k>=j+g+g; k-=g){
          count++;
          A[k] = A[k-g];
        }
        A[j+g] = v;
        break;
      }
    }
  }
}

