      for(int j=1;j<amount;j++){ //inserting sort
        if(a[first+j*spread[k]]>a[first+(j-1)*spread[k]]) continue;
        int l;  
        for(l=j-1;l!=-1;l--) if(a[first+j*spread[k]]>=a[first+l*spread[k]]) break;
        l++;
        for(int p=first+j*spread[k];p>first+l*spread[k];p-=spread[k]){
          swap(a[p],a[p-spread[k]]);
