            j = j - g;
            cnt++;
        }
        A[j+g] = v;
    }
    return cnt;
}
void Reverse(TList& List)
{
    TList R;
    for(TList::reverse_iterator It = List.rbegin();
        It != List.rend();
        ++It)
    {
        R.push_back(*It);
    }
    std::swap(R, List);
}
TList GetG(int Max)
{
    TList G;
    int h = 1;
    G.push_back(h);
    while(h <= Max){
        h = 3 * h + 1;
        G.push_back(h);
    }
    Reverse(G);
    return G;
}
int shellSort(TList& A, const TList& G)
{
    int cnt = 0;
    for(TList::reverse_iterator It = A.rbegin();
        It != A.rend();
        ++It){
        cnt += insertionSort(A, *It);
    }
    return cnt;
}

