void insertionSort(int A[], int n, int g){
    int v,j;
    for(int i = g; i < n; ++i){
        v = A[i];
        j = i - g;
        while(j >= 0 && A[j] > v){
            A[j+g] = A[j];
            j = j - g;
            cnt++;
        }
        A[j+g] = v;
    }

}

void shellSort(int A[],int n){
    // 数列G = {1,4,13,40,121,364,....}(g(n+1) = 3g(n)+1)を生成
    for(int h=1; ; ){
        if(h > n) break;
        G.push_back(h);
        h = 3*h+1;
    }
    for(int i = G.size()-1;i >= 0;--i){
        insertionSort(A,n,G[i]);
    }

}
