int G[105];
int make_G(int n){
    G[0] = 1;
    int i = 0, j = 0;
    while (n >= (3 * G[j] + 1) && j < 99)
    {
        G[j+1] = 3 * G[j] + 1;
        j++;
    }
    int m = j+1;
    while (i < j)
    {
        swap(&G[i], &G[j]);
        i++; 
        j--;
    }

    return m;
}

int shell_sort(int A[], int n){
    cnt = 0;
    int m = make_G(n);
    for (int i = 0; i < m; i++)
    {
        insertion_sort(A, n, G[i]);
    }

    return m;
}

