int main(){
  int n,m,tmp,cnt=0;
  vector <int> a,spread;

  cin>>n;
  for(int i=0;i<n;i++){ //input original
    cin>>tmp;
    a.push_back(tmp);
  }
  for(int i=0,tmp=1;tmp<=n;i++){ //make spread vector
    spread.insert(spread.begin(),tmp);
    tmp=3*tmp+1;
  }
  m=spread.size();
  cout<<m<<endl; //output spread amount
  for(int i=0;i<m-1;i++) cout<<spread[i]<<" ";
  cout<<spread[m-1]<<endl; //output all spread
  for(int k=0;k<m;k++){  //testing all spread
    for(int i=0;i+spread[k]<n;i++){
      int end=i+spread[k],first=i%spread[k]; //list first
      int amount=(end-first)/spread[k]+1; //list amount
      for(int j=1;j<amount;j++){ //inserting sort
        if(a[first+j*spread[k]]>a[first+(j-1)*spread[k]]) continue;
	int l;	
	for(l=j-1;l!=-1;l--) if(a[first+j*spread[k]]>a[first+l*spread[k]]) break;
	l++;
	for(int p=first+j*spread[k];p>first+l*spread[k];p-=spread[k]){
	  swap(a[p],a[p-spread[k]]);
	  cnt++;
	}
      }
      //cout<<"check vector cnt:"<<cnt<<endl; //debug
      //for(int i=0;i<n-1;i++) cout<<a[i]<<" ";
      //cout<<a[n-1]<<endl<<endl;
    }
  }
  cout<<cnt<<endl; //output cnt&answer vector
  for(int i=0;i<n;i++) cout<<a[i]<<endl;
  return 0;
}

