int insertSort( int data[], int dataNum, int gap ) {
    int cnt = 0;
    for( int offset = 0; offset < gap; offset++ ) {
        for( int i = 0; i + gap < dataNum; i = i + gap ) {
            int cur = i+gap;
            int edgeVal = data[cur];
            while( cur - gap >= 0 && data[cur-gap] > edgeVal ) {
                data[cur] = data[cur - gap];
                cur = cur - gap;
                cnt++;
            }
            data[cur] = edgeVal;
        }
    }

    return cnt;
}

std::vector<int> getGaps( int dataNum ) {
    std::vector<int> ret;
    int i = 0;
    while( true ) {
        if( i > dataNum ) {
            break;
        }
        ret.push_back(i);
        i = 2*i + 1;
    }
    return ret;
}

