vector<int> sequence_g(int n)
{
    vector<int> G;
    G.push_back(1);

    int next = G.back() * 3 + 1;
    while (next < n)
    {
        G.push_back(next);
        next = G.back() * 3 + 1;
    }
    reverse(G.begin(), G.end());

    return G;
}
