void InsertionSort(vector<int> &store_num, int num_cnt, int step)
{
    for (int i = step; i < num_cnt; i++)
    {
        int val = store_num[i];
        int j = i - step;
        while ((j >= 0) && (store_num[j] > val))
        {
            store_num[j + step] = store_num[j];
            j -= step;
            swap_cnt++;
        }
        store_num[j + step] = val;
    }

