{
    for (int step = 1; ; )
    {
        if (step > num_cnt)
        {
            break;
        }

        store_step.push_back(step);
        step = 3 * step + 1;
    }

    for (int i = (int)store_step.size() - 1; i >= 0; i--)
    {
        InsertionSort(num, num_cnt, store_step[i]);
    }

    return ;
}

