void insertionSort(int a[], int n, int g) {
  int v, j;
  for (int i = g; i < n; i++) {
    v = a[i];
    for (j = i - g; 0 <= j; j = j - g) {
      if (a[j] < v) break;
      a[j + g] = a[j];
      cnt++;
    }
    a[j + g] = v;
  }
}

void shellSort(int a[], int n) {
  cnt = 0;
  for (int h = 1;;) {
