void insertionSort(int nIn[],int nNum,int nG)
{
	int nMin=0;
	int j=0;
	for(int i=nG;i<=nNum-1;++i)
	{
		nMin=nIn[i];
		j=i-nG;
		while(j>=0 && nIn[j]>nMin)
		{
			nIn[j+nG]=nIn[j];
			j-=nG;
			nCnt++;
		}
		nIn[j+nG]=nMin;
	}
}

