static vector<uint32_t> G;

uint64_t insersion_sort(int64_t dist)
{
  uint64_t count = 0;
  for (uint32_t i = dist; i < array.size(); i++) {
    for (int32_t j = i; j >= dist; j -= dist) {
      if (array[j - dist] > array[j]) {
        swap(array[j - dist], array[j]);
        count++;
      }
    }
  }

  return count;
}

uint64_t shell_sort()
{
  uint32_t i = 1;
  while (i <= array.size()) {
    G.push_back(i);
    i = 3 * i + 1;
  }

  uint64_t count = 0;

  for (int32_t j = G.size() - 1; j >= 0; j--) {
    count += insersion_sort(G[j]);
  }

  return count;
}

