void ShellSort(int A[], int n) {
    int h = 1;
    while(h <= n) {
        G.insert(G.begin(), h);
        h = 3 * h + 1;
    }
    m = int(G.size());

    for(int i = 0; i < m; i++) InsertarionSort(A, n, G[i]);
}

