	{
		int v = Numbers[i];
		int j = i - Interval;
		while(j >= 0 && Numbers[j] > v)
		{
			Numbers[j+Interval] = Numbers[j];
			j -= Interval;
			InsertCount++;
		}
		Numbers[j+Interval] = v;
	}
}

