string shell_sort(string str, int ary_size, int m, int* G) {
	int* ary = new int[ary_size];
	stringstream ss(str);
	string buff;
	int cnt = 0;
	while (getline(ss, buff, ' ')) {
		stringstream tss(buff);
		tss >> ary[cnt];
		cnt++;
	}

	// main.
	for (int i = 0; i < m; i++) {
		insert_sort_4_shell(ary, ary_size, G[i]);
	}

	return intArrayToString(ary, ary_size);
}

int* insert_sort_4_shell(int* ary, int ary_size, int g) {

	// main.
	for (int i = g; i < ary_size; i++) {
		int v = ary[i];
		for (int j = i - g; j >= 0 && v < ary[j]; j -= g) {
			ary[j + g] = ary[j];
			ary[j] = v;
		}
	}

	return ary;
}

string intArrayToString(int* ary, int ary_size) {
	string str = "";
	for (int i = 0; i < ary_size; i++) {
		if (i == ary_size - 1) {
			str += to_string(ary[i]);
		}
		else {
			str += to_string(ary[i]) + " ";
		}
	}
	return str;
}

