template<typename I, typename F>
void for_each2(I begin, I end, F fnc){
    fnc(true, false, *begin);
    while(++begin != end - 1) fnc(false, false, *begin);
    fnc(false, true, *begin);
}

int cnt = 0;

template<typename T>
void shell_sort(T ar, int n, int g){
    for (int i = g; i < n; i++) {
        auto v = ar[i];
        int j = i - g;
        while (j >= 0 && ar[j] > v ) {
            ar[j+g] = ar[j];
            j -= g;
            cnt++;
        }
        ar[j+g] = v;
    }
}

