int insertionSort(int a[], int n, int g) {
	// 针对元素个数为n的数组a，以间隔g进行插入排序
	// 例：a=[3,8,5,2,7,9,1,4],g=2, 则分为[3，5，7，1]，[8,2,9,4] 两组分别进行插入排序
	int cnt = 0;
	for (int i = g; i < n; i++) {
		int v = a[i]; // 待插入的值
		int j = i - g; // 同组的前一个元素 例i=2，属于第1组，前一个元素为3,下标为0
		while (j >= 0 && a[j] > v) {
			swap(a[j], a[j + g]);
			j = j - g;
			cnt++;
		}
		a[j + g] = v;
	}
	return cnt;
}

void shellSort(int a[], int n,int &cnt, int &m,int G[]) {
	int n1 = n;
	n1 = n;
	int i = 0;
	while(n1/3>0) {
		G[i] = n1 / 3 + 1;
		n1 = n1 / 3 + 1;
		m++;
		i++;
	}
	G[i] = 1;
	for (int j = 0; j < m; j++) {
		cnt+=insertionSort(a, n, G[j]);
	}
}

