    constexpr int N = max_size();
    const auto r = std::make_unique<int[]>(N);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &r[i]);
    }

    shell_sort(r.get(), n);
    print(r.get(), n, '\n');

    return 0;
}

