int insertionSort(vector<int> &A, int N, int g, int &cnt) {
  int v, j;

  for (int i = g; i < N; i++) {
    v = A.at(i);
    j = i - g;

    while (j >= 0 && A.at(j) > v) {
      A.at(j + g) = A.at(j);
      j -= g;
      cnt++;
    }

    A.at(j + g) = v;
  }
}

int shellSort(vector<int> &A, int N) {
  int cnt = 0;
  vector<int> tmpG;
  int index = 0;

  while (true) {
    int tmp = 0;

    // 1 から始めて 3n + 1 していく
    if (index == 0) {
      tmp = 1;
    } else {
      tmp = (3 * tmpG.at(index - 1)) + 1;
    }

    if (tmp <= N) {
      tmpG.push_back(tmp);
    } else {
      break;
    }

    index++;
  }

  int m = 0;
  vector<int> G(tmpG.size());
  int indexG = tmpG.size() - 1;

  cout << tmpG.size() << endl;

  while (true) {
    G.at(m) = tmpG.at(indexG);

    cout << G.at(m);

    if (m == tmpG.size() - 1) {
      cout << endl;
    } else {
      cout << " ";
    }

    if (indexG == 0) {
      break;
    }

    m++;
    indexG--;
  }

  for (int i = 0; i < tmpG.size(); i++) {
    insertionSort(A, N, G.at(i), cnt);
  }

  cout << cnt << endl;
}

