  for (auto &&a : A) std::cin >> a;

  uint32_t count = 0;
  std::vector<uint32_t> G;
  for (size_t i = 1; i <= N; i = 3 * i + 1) G.push_back(i);
  std::reverse(G.begin(), G.end());

  for (auto &&g : G) {
    for (size_t i = g; i < N; i++) {
      for (size_t j = 0; i >= g * (j + 1); j++) {
        if (A[i - g * j] >= A[i - g * (j + 1)]) break;
        auto temp = A[i - g * (j + 1)];
        A[i - g * (j + 1)] = A[i - g * j];
        A[i - g * j] = temp;
        count++;
      }
    }
  }

  std::cout << G.size() << std::endl;
  for (uint32_t i = 0; i < G.size() - 1; i++) std::cout << G[i] << " ";
  std::cout << G.back() << std::endl;
  std::cout << count << std::endl;
  for (auto &&a : A) std::cout << a << std::endl;

  return 0;
}

