void generalizedInsertionSort(int A[], int n, int g) {
  for (int i = g; i < n; i++) {
    int key = A[i];
    int j = i - g;
    while (j >= 0 && A[j] > key) {
      A[j+g] = A[j];
      j -= g;
      cnt++;
    }
    A[j+g] = key;
  }
}

