  vector<int> G;
  int g = (n / 2 == 0) ? 1 : n / 2;
  while (g > 0) {
    G.push_back(g);
    g /= 2;
  }

  for (int g : G) {
    generalizedInsertionSort(A, n, g);
  }

  cout << G.size() << endl;
  for (int g : G) cout << g << " ";
  cout << endl;
}

