int insertionSort(vector<int>& v, int g, int cnt)
{
    for (size_t i = g; i < v.size(); ++i) {
        int e = v[i];
        int j = i - g;
        while (j >= 0 && v[j] > e) {
            v[j + g] = v[j];
            j = j - g;
            ++cnt;
        }
        v[j + g] = e;
    }
    return cnt;
}

