        scanf("%d", &t);
        v.push_back(t);
    }
    int cnt = 0;

    deque<int> g;
    auto lim = static_cast<int>(floor(v.size() / 3.0));
    auto pow = [](int base, int ex) {
        int r = 1;
        for (auto i = 0; i < ex; ++i) {
            r *= base;
        }
        return r;
    };
    auto e = [pow](int n) { return (pow(3, n) - 1) / 2; };
    for (int i = 1; true; ++i) {
        auto r = e(i);
        if (r > lim) {
