template<class T>
void selectionSort(T* array, int size, int g)
{
        int min;
        for(int i=g-1; i<size-1; i+=g){
                min = i;
                for(int j=i+g; j<size; j+=g){
                        if( array[j] < array[min] ){ min = j; }
                }
                T tmp;
                if( min != i){
                        tmp = array[min];
                        array[min] = array[i];
                        array[i] = tmp;
                        cnt++;
                }
        }
}

