void getGarray(int arraySize, int *&pG, int &gSize) {
	stack<int> s;
	int i = 1;
	while (i <= arraySize) {
		s.push(i);
		i *= 2;
	}
	gSize = s.size();
	pG = new int[gSize];
	for (int i = 0; i < gSize; i++) {
