int insertion_sort(int n, int elements[], int g)
{
	int cnt = 0;
	for (int i = g; i < n; i++) {
		int key = elements[i], j = i - g;
		while (key < elements[j] && 0 <= j) {
			elements[j + g] = elements[j];
			j -= g;
			cnt++;
		}
		elements[j + g] = key;
	}
	return cnt;
}

void shell_sort(int n, int elements[])
{
	int cnt = 0, m = 0, g_calc = 1, g[100];
	while (g_calc <= n) {
		g[m] = g_calc;
		g_calc *= 2;
		m++;
	}
	cout << m << endl;
	for (int i = m - 1; 0 <= i; i--) {
		cout << g[i] << (i == 0 ? "" :  " ");
		cnt += insertion_sort(n, elements, g[i]);
	}
	cout << endl;
	cout << cnt << endl;
}

