vector<bool> prime_table(int n){
	if(n==1) return vector<bool>(n+1,0);
	vector<bool> table(n+1,1);
	table[0]=table[1]=0;
	table[2]=1;
	for(int i=2;i*i<=n;++i){
		if(!table[i]) continue;
		for(int j=2;i*j<=n;++j) table[i*j]=0;
	}
	return table;
}

