void insertionSort(std::vector<int> &A,int g,long long int &count){
  for(int i=g;i<A.size();i++){
    int tmp = A[i];
    int j=i-g;

    while(j>=0 && A[j]>tmp){
      A[j+g]=A[j];
      j-=g;
      count++;
    }
    A[j+g]=tmp;
  }
}


std::vector<int> shellsort(std::vector<int> &A,long long int &count){
  std::vector<int> G;
  int i=0;
  while(3*i+1<A.size()){
    G.push_back(3*i+1);
    i++;
  }

  for(i=G.size()-1;i>=0;i--){
    insertionSort(A,G[i],count);
  }

  return G;
}

