template<typename T>
void Print(const T* pArray, int size)
{
	for (int i = 0; i < size; ++i)
		cout << pArray[i] << (i != size - 1 ? " " : "\n");
}

template<typename T>
void InsertionSort(T* pArray, int size, int step, int& count)
{
	// [0]..[i][j]..[size - 1]
	for (int j = step; j <= size - 1; j++)
	{
		T value = pArray[j];
		int i = j - step;
		while (i >= 0 && pArray[i] > value)
		{
			pArray[i + step] = pArray[i];
			i -= step;
			++count;
		}

		pArray[i + step] = value;
	}
}

template<typename T>
void ShellSort(T* pArray, int size)
{
	vector<int> G;
	int h = 1;
	do
	{
		G.push_back(h);
		h = h * 3 + 1;
	} while (h < size);

	cout << G.size() << endl;
	for(int i = G.size() - 1; i >= 0; --i)
		cout << G[i] << (i != 0 ? " " : "\n");
	int count = 0;
	for (int i = G.size() - 1; i >= 0; --i)
		InsertionSort(pArray, size, G[i], count);
	cout << count << endl;
	for (int i = 0; i < size; ++i)
		cout << pArray[i] << endl;
}

