using namespace std;

int insertion_sort(int A[], int N , int g) {
    int count = 0;
	for (int i = g; i < N; ++i) {
		int v = A[i];
        int j = i - g;
		for (; j >= 0 && A[j] > v; j -= g) {
			A[j + g] = A[j];
            ++count;
		}
        A[j + g] = v;
	}
    return count;
}

int shell_sort(int A[], int N, vector<int> G){
    int count = 0;
    for(auto g = G.end() - 1, begin = G.begin(); g >= begin; --g){
        count += insertion_sort(A, N, *g);
    }
    return count;

}

