	for ( i = gap ; i < A.size() ; i++ )
	{
		v = A[i];
		for ( j = i-gap ; j>=0 && A[j]>v ; j-=gap )
		{
			A[j+gap] = A[j];
			count++;
		}
		A[j+gap] = v;
	}
	return count;
}

