  {
    if (i != argviGap.size() - 1) cout << " ";
    cout << argviGap[i];
  }
  cout << endl;

  cout << argiSortCnt << endl;

  for (int i = 0; i < argviSort.size(); i++)
    cout << argviSort[i] << endl;
}

