void insertionSort(vector<int>& line, const int n, const int gap)
{
    for (auto i = gap; i < n; i++) {
        int key = line.at(i);

        auto j = i - gap;
        while (j >= 0 && line.at(j) > key) {
            line.at(j + gap) = line.at(j);
            g_cnt++;
            j -= gap;
        }

        line.at(j + gap) = key;
    }
}

