void insertionsort(int a[], int n, int g)
{
    for(int i = g; i < n; i++)
    {
        int v = a[i];
        int j = i - g;
        while(j >= 0 && a[j] > v)
        {
            a[j + g] = a[j];
            j -= g;
            cnt++;
        }
        a[j + g] = v;
    }
}

void shellsort(int a[], int n)
{
    for(int h = 1;;)
    {
        if(h > n) break;
        g.push_back(h);
        h = 3 * h + 1;
    }

    for(int i = g.size() - 1; i >= 0; i--) insertionsort(a, n, g[i]);
}

