/*
 * 希尔排序思路：
 * 1. 选择增量进行分组
 * 2. 在每组内进行插入排序
 * 3. 缩小增量再执行1、2，直到增量为1（增量为1时也要在执行一次）
 */

long long cnt;
int a[1000001];
int n;
vector<int> G;

// 间隔为g的插入排序
void insertionSort(int a[], int n, int g){
    for (int i = g; i < n; i++){
        int v = a[i];
        int j = i - g;
        while(j >= 0 && a[j] > v){// 在每个分组内，进行插入排序
            a[j+g] = a[j];
            j -= g;
            cnt++;
        }
        a[j+g] = v;
    }
}

void shellSort(int a[], int n){
    // 生成间隔数列G
    int h = 1;
    while(h <= n){
        G.push_back(h);
        h = 3*h+1;
    }
    // 指定插入间隔g = G[i]
    for (int i = G.size()-1; i >= 0; i--){
        insertionSort(a, n, G[i]);
    }
}

