    for (int i = G.size()-1; i >= 0; i--){
        if (i != 0){
            printf("%d ", G[i]);
        }else{
            printf("%d\n", G[i]);
        }
    }
    printf("%d\n", cnt);
    for (int i = 0; i < n; i++){
        printf("%d\n", a[i]);
    }
    return 0;
}

