int readint() {
	char ch = getchar_unlocked();
	int res = 0;
	while('0' <= ch && ch <= '9') {
		res = res * 10 + (ch - '0');
		ch = getchar_unlocked();
	}
	return res;
}
char buf[1024];
void writeint(int x, char endch) {
	int ptr = 0, g;
	while(x > 0) {
		g = x / 10;
		buf[ptr++] = x - g * 10;
		x = g;
	}
	if(ptr == 0) {
		buf[ptr++] = 0;
	}
	while(ptr--) {
		putchar_unlocked(buf[ptr] + '0');
	}
	putchar_unlocked(endch);
}
