void insertion_sort(int A[], int N, int g){
  for(int i = g; i<N; i++){
    int v = A[i];
    int j = i - g;
    while(j >= 0 && A[j] > v){
      A[j+g] = A[j];
      j -= g;
      cnt++;
    }
    A[j+g] = v;
  }
}

void shell_sort(int A[], int N){
  for(int h = 1; ; ){
    if(h > N)
      break;
    G.push_back(h);
    h = 3*h +1;
  }

  for(int i = G.size() - 1; i >= 0; i--){
    insertion_sort(A,N,G[i]);
  }
}

