vector<int> insertionSort(vector<int> A, int n, int g) {
  for (int i = g; i < n; i++) {
    int v = A[i];
    int j = i - g;
    while (j >= 0 && A[j] > v) {
      A[j+g] = A[j];
      j = j - g;
    }
    A[j+g] = v;
  }
  return A;
}

vector<int> shellSort (vector<int> A, int n) {
  vector<int> G;
  int tmp = n;
  while (tmp >= 1) {
    tmp /= 2;
    G.push_back(tmp);
  }

  int m = G.size();
  for (int i = 0; i < m; i++) {
    A = insertionSort(A, n, G[i]);
  }

  cout << m << endl;
  for (int i = 0; i < m; i++) {
    cout << G[i];
    if (i != m-1) cout << ' ';
    else cout << endl;
  }
  return A;
}

