void insertionSort(int a[], int n, int g, int & cnt)
{
  for(int i = g; i < n; ++i){
    //show
    //for(int i = 0; i<n ; ++i){ cout << a[i] <<" "; }
    // cout << endl;
    // cout << "cnt: " << cnt << endl;
    // cout << "g:   " << g << endl;
    // cout << "---" <<endl;

    int v = a[i];
    int j = i - g;

    while(j >= 0 && a[j] > v){
      a[j+g] = a[j];
      j = j - g;
      ++cnt;
    }
    a[j+g] = v;
  }
}


