int insertion_sort(int_vec& v, int g) {
    int count = 0;
    for (int i = g; i < v.size(); ++i) {
        int x = v[i];
        int j = i - g;
        for (; j >= 0 && v[j] > x; j -= g) {
            v[j+g] = v[j];
            ++count;
        }
        v[j+g] = x;
    }
    return count;
}

int shell_sort(int_vec& v) {
    int m = min(static_cast<int>(v.size() / 3) - 1, 100);
