int intervalSize(int max) {
    int n = 1;
    int g = 1;
    while ( (g = 3 * g + 1) <= max) n++;
    return n;
}

void intervals(int gn, int gs[]) {
    if (gn <= 0) return;
    gs[gn - 1] = 1;
    for (int i = gn - 1; i > 0; i--) {
        gs[i - 1] = 3 * gs[i] + 1;
    }
}

int insertionSort(int N, int A[], int g) {
    int n_swapped = 0;
    for (int i = g; i < N; i++) {
        int v = A[i];
        int iBef = i - g;
        while (0 <= iBef && v < A[iBef]) {
            A[iBef + g] = A[iBef];
            iBef -= g;
            n_swapped++;
        }
        A[iBef + g] = v;
    }
    return n_swapped;
}

int shellSort(int N, int A[], int gn, int gs[]) {
    int n_swapped = 0;
    for (int i = 0; i < gn; i++) {
        n_swapped += insertionSort(N, A, gs[i]);
    }
    return n_swapped;
}

