    for(auto i=0; i<n; i++) {
        int v{a[i]}, j{i-g};
        while(j>=0 && a[j]>v) {
            a[j+g] = a[j];
            j= j-g;
            cnt++;
        }
        a[j+g] = v;
    }
    return cnt;
}

void shellSort(int* a, const int n) {
    std::vector<int> g{};
    int h{};
    while(h<n/3) {
        h = 3*h+1;
        g.push_back(h);
    }
    if(!g.size()) g.push_back(1);
    const size_t m{g.size()};
    std::cout << m << std::endl;
    for(auto i=m; i>0; i--) std::cout << g[i-1] << ((i>1) ? " " : "\n");
    int cnt{};
    for(auto i=m; i>0; i--) {
        cnt += insertionSort(a, n, g[i-1]);
    }
    std::cout << cnt << std::endl;
}

