  std::ios::sync_with_stdio(false);
  unsigned n,buf;
  std::cin >> n;
  std::vector<unsigned> a(n);
  for(unsigned i = 0; i < n; i++){
    std::cin >> buf;
    a[i] = buf;
  }
  shell_sort(a.data(),a.size());
  for(auto &v : a){
    std::cout << v << '\n';
  }
}

