// global
int cnt = 0;

void InsertionSort(vector<int> &vec, int g = 1) {
    /*
     * 挿入ソート(トランプの並べ替え)
     * 未ソート部分の一番左端からスタート
     * 挿入できるインデックスを取得して間に挿入
     */
    for (int i = g; i < vec.size(); ++i) {
        int left = vec.at(i);  // 未ソートの左端

        // ソート済みと比較していく
        // シェルソートの間隔はg
        int j = i - g;  // ソート済みの右端のインデックス
        // j = 0, g, 2g, 3g, ...

        // 条件は左から順に読み取られることに注意
        while (j >= 0 && vec.at(j) > left) {
            vec.at(j + g) = vec.at(j);
            j -= g;
            cnt++;
        }
        int insert_idx = j + g;  // 最後引かれた分をg足してる
        vec.at(insert_idx) = left;
        // printVec(vec);
    }

}

int ShellSort(vector<int> &vec) {
    vector<int> G;  // 長さ m のベクトル
    // Gを決める
    int i = 1;
    do  {
        G.push_back(i);
        i = 3*i + 1;
    } while (i < vec.size());

    // output
    int m = G.size();
    cout << m << endl;
    reverse(ALL(G));
    printVec(G);

    REP(i, m) {
        InsertionSort(vec, G.at(i));
    }
    return cnt;
}


int main() {
    /*
     * Shell Sort
     * g離れた要素のみをソートする
     */
    // input
    int N;
    cin >> N;
    vector<int> vec(N);
    REP(i, N) cin >> vec.at(i);

    // calculation
    ShellSort(vec);
    cout << ::cnt << endl;
    REP(i, N) {
        cout << vec.at(i) << endl;
    }
    return 0;
}


