};

int ShellSort::insertSort( int *a, int n, int g)
{
  int cnt = 0;

  for ( int i = g; i < n; i++ )
    {
      int v = a[i];
      int j = i - g;
      while (j >= 0 && a[j] > v)
        {
          a[j+g] = a[j];
          j -= g;
          cnt++;
        }
      a[j+g] = v;
    }
  return cnt;
}

int ShellSort::shsort( int *a, int n, int *m, int *g )
{
  int cnt = 0;

  int i = 0;
  for (int l = n / 2; l > 0; l /= 2)
    {
      (*m)++;
      g[i++] = l;
    }

  for ( int i = 0; i < *m; i++ )
    {
      cnt += insertSort(a, n, g[i]);
    }

  return cnt;
}

