int* insert_sort_4_shell(int* ary, int ary_size, int g, int &counter) {

	// main.
	for (int i = g; i < ary_size; i++) {
		int v = ary[i];
		for (int j = i - g; j >= 0 && v < ary[j]; j -= g) {
			ary[j + g] = ary[j];
			ary[j] = v;
			counter++;
		}
	}

	return ary;
}

