int InsertionSort_r(int arr[], int N, int range)
{


	int cnt=0, comp, j;


	for( int i=0; i<range ; i++) {


		for( int compindex = i + range ; compindex < N ; compindex += range ) {


			comp=arr[compindex];

			j=range;

			for( ; compindex - j >= 0 ; j+=range ) {

				if( comp < arr[ compindex - j ] ){
					arr[ compindex - j + range ] = arr[ compindex - j ];
					cnt++;
				}
				else 
					break;
			}

			arr[ compindex - j + range ] = comp;

		}

	}

	return cnt;
}

