#include <iostream>
#define NMAX 	1000000
#define MMAX	100

int A[NMAX];

int insertionSort(int array[], int n, int g){
	int cnt = 0;

	for(int init=0 ; init<g ; init++){
		for(int i=g+init ; i<n ; i+=g){
			int target = array[i];
			int j = i;
			while( (j >= g) && (target < array[j-g]) ){
				array[j] = array[j-g]; // Shift right
				j -= g;
				cnt++;
			}
			array[j] = target;
		}
	}

	return cnt;
}

