	G[0] = 1;
	int G_n1 = 3*G[0] + 1;
	while((G_n1 < n) && (m < MMAX-1)){
		G[m] = G_n1;
		G_n1 = 3*G[m] + 1;
		m++;
	}

	for(int i=m-1 ; i>=0 ; i--){
		cnt_g = insertionSort(A, n, G[i]);
		cnt_all += cnt_g;
	}

	// Output gap value
