#include <iostream>
#include <vector>
using namespace std;

void swap(int *from, int *to){
    int tmp = *from;
    *from = *to;
    *to = tmp;
}

int InsertionSort(vector<int> &A, int g){
    int N = A.size();
    int cnt = 0;
    for(int i = g; i < N; ++i){
        int idx = i;
        while(idx > 0 && (A[idx - g] > A[idx])){
            swap(&A[idx - g], &A[idx]);
            idx = idx - g;
            ++cnt;
        }
    }
    return cnt;
}

int ShellSort(vector<int> &A, vector<int> &G){
    int N = A.size();
    int cnt = 0;
    int g = 1;
    while(g < N){
        G.push_back(g);
        g = 3 * g + 1;
    }
    for(int i = G.size() - 1; i >= 0; --i){
        cnt += InsertionSort(A, G[i]);
    }

    return cnt;
}

int main(void){
