    int cnt = ShellSort(A, G);
    int m = G.size();

    cout << m << endl;
    for(int i = m - 1; i >= 0; --i){
        cout << G[i];
        if(i != 0)
            cout << " ";
    }
    cout << endl << cnt << endl;
    for(int i = 0; i < N; ++i)
        cout << A[i] << endl;

    return 0;
}

