void insertion_sort(int N, int A[], int g){
    //挿入ソート 計算量 O(N**2)
    for(int i = g; i < N; i++){
        int v = A[i];
        int j = i - g;
        //i番目の要素とi-g to 0番目 => (j)の要素を比較していく
        while(j >= 0 && A[j] > v){
            //gだけ後ろにずらしていく
            A[j+g] = A[j];
            j -= g;
            cnt++;
        }
        A[j+g] = v;
    }
}

