	for (int i = g; i < n; i++) {
		int v = p[i];
		int j = i - g;
		while (j >= 0 && p[j] > v) {
			p[j + g] = p[j];
			j -= g;
			cnt=cnt+1;
		}
		p[j + g] = v;
	}
}

void shellSort(int*p, int n) {
	int h = 0;
	for (int i=0;;i++) {
		if (h > n) break;
		h = 9 * pow(4, i) - 9 * pow(2, i) + 1;
		G.push_back(h);

	}

    for (int i= G.size()-1;i>=0;i--)
	{
		insertionSort(p, n, G[i]);
	}
}

