#define REP(i,n) for (ll i = 0; i < (n); ++i)

template<typename T>
void print_vector(vector<T>& a){
    REP(i, a.size()){
        cout << a.at(i);
        if(i + 1 < a.size()){
            cout << ' ';
        }
    }
    cout << endl;
}

void insertion_sort(vector<ll>& a, ll g, ll& cnt){
    for(ll i = g; i < a.size(); ++i){
        const ll v = a.at(i);
        ll j;
        for(j = i - g; j >= 0 && a.at(j) > v; j -= g, cnt++){
            a.at(j + g) = a.at(j);
        }
        a.at(j + g) = v;
    }
}

