//挿入ソート関数
//要素数ｎの配列Aを、間隔int gだけ離れた要素についてだけソートを繰り返す。
void insertionSort(int A[], int n, int g)
{
	int v, j;

	for (int i = g; i < n; i++)
	{
		v = A[i];						//ソート用のバッファvに代入
		j = i - g;						//iより gだけ小さい要素 j

		while (j >= 0 && A[j] > v)		//挿入ソート。jが0以上、かつAのj番目の要素とi番目の要素が逆順のとき、順序入れ替え
		{
			A[j + g] = A[j];
			j = j - g;	
			cnt++;
		}
		A[j + g] = v;
	}
}

//シェルソート関数
//関数内で、ソート間隔指定用の数列G作成
int shellSort(int A[], int n)
{
	for (int h = 1;;)
	{
		if (h > n)	break;
		G.push_back(h);
		h = 3 * h + 1;
	}

	for (int i = G.size()-1 ; i >= 0 ; i--)
	{
		insertionSort(A, n, G[i]);
	}
	return G.size();
}

