 int insertion_sort(std::vector<int> a, int n, int gap) {
	int count = 0;
	for (int i = gap; i < n; ++i) {
		int v = a[i];
		int j = i - gap;
		while (j >= 0 && a[j] > v) {
			a[j + gap] = a[j];
			j -= gap;
			count++;
		}
		a[j + gap] = v;
	}
	return count;
}
