using namespace std;

long long cnt;
int n, A[1000000];
vector<int> G;

void insertion_sort(int A[], int n, int g) {
    int v, j;

    for (int i = g; i < n; i++) {
        v = A[i];
        j = i - g;
        while (j >= 0 && A[j] > v) {
            A[j + g] = A[j];
            cnt++;
            j -= g;
        }
        A[j + g] = v;
    }
}

void shell_sort(int A[], int n) {

    for (int h = 1; h <= n; h = 3 * h + 1) {
        G.push_back(h);
    }

    for (int i = G.size() - 1; i >= 0; i--) {
        insertion_sort(A, n, G[i]);
    }
}

int main () {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d", &A[i]);
    cnt = 0;

    shell_sort(A, n);

    printf("%d\n", G.size());
    for (int i = G.size() - 1; i >= 0; i--) {
        printf("%d", G[i]);
        if(i) printf(" ");
    }
    printf("\n");
    printf("%d\n", cnt);
    for (int i = 0; i < n; i++) printf("%d\n", A[i]);

    return 0;
}

