    int A[N];
    for (int i = 0; i < N; i++)
        cin >> A[i];

    vector<int> G;
    intervals(N, G);

    int n_swapped = shellSort(N, A, G);

    cout << G.size() << endl << G.back();
    for (int i = G.size() - 2; i >= 0; i--)
        cout << " " << G[i];
    cout << endl;

    cout << n_swapped << endl;
    for (int i = 0; i < N; i++)
        cout << A[i] << endl;

    return 0;
}

