#define REP(i,a,b) for(i=a;i<b;i++)
#define rep(i,n) REP(i,0,n)

using namespace std;

int insertionSort(int A[], int n, int g) {
	int i, j, v;
	static int cnt=0;
	int k;
	REP(i,g,n) {
		v = A[i];
		j = i - g;
		while (j >= 0 && A[j] > v) {
			A[j+g] = A[j];
			// rep(k,n) cout << A[k] << (k < n-1 ? " ":"\n");
			j = j - g;
			cnt += 1;
			if (cnt > floor(pow(n,1.5))) break;
		}
		A[j+g] = v;
		// rep(k,n) cout << A[k] << (k < n-1 ? " ":"\n");
	}
	return cnt;
}
void shellSort(int A[], int n) {
	int i,cnt = 0, m = n/2;
	int G[m];
	for(i=m-1;i>=0;i--) {
		G[m-i-1] = pow(m,i);
	}
	cout << m << endl;
	rep(i,m) cout << G[i] << (i < m-1 ? " ":"\n");
	rep(i,m) cnt = insertionSort(A, n, G[i]);
	cout << cnt << endl;
}
int main() {
    ios::sync_with_stdio(false);
	int n,m,i;
	cin >> n;
	int A[n];
	rep(i,n) cin >> A[i];
	shellSort(A, n);
	rep(i,n) cout <<  A[i] << endl;
}

