using namespace std;

static void insersion_sort(int32_t array[], size_t size, uint32_t interval,
                           void (*callback)(int32_t array[], uint32_t index, uint32_t index2))
{
  for (int32_t i = 0; i < size; i++) {
    for (int32_t j = ((size - 1 - i) / interval) * interval + i; j >= i + interval; j -= interval) {
      if (array[j - interval] > array[j]) {
        swap(array[j - interval], array[j]);
        if (callback != nullptr) {
          callback(array, j - interval, j);
        }
      }
    }
  }
}

vector<uint32_t> shell_sort(int32_t array[], size_t size, void (*callback)(int32_t array[], uint32_t index, uint32_t index2))
{
  if ((array == nullptr) || (size == 0)) throw runtime_error("arguments error");

  vector<uint32_t> vec;
  vec.push_back(1);
  for (uint32_t gn = 4; gn < size; gn = 3 * gn + 1) {
    vec.push_back(gn);
  }

  for (int32_t i = vec.size() - 1; i >= 0; i--) {
    insersion_sort(array, size, vec[i], callback);
  }

  return vec;
}

