template<typename U>
int sort_by_insertion(U *x, int n, int g) {
	int cnt = 0;
	for (int i=g; i<n; ++i) {
		U v = x[i];
		int j = i-g;
		while (j>=0 && x[j] > v) {
			x[j+g] = x[j];
			j = j-g;
			cnt++;
		}
		x[j+g] = v;
	}
	return cnt;
}

template<typename U>
std::tuple<int, std::vector<int> > sort_by_shell(U *x, int n) {
	std::vector<int> G;
	int cnt = 0;
	//int g = n / 2; // たぶんここがなにが想定と違うらしい.
	int g = n; // たぶんここがなにが想定と違うらしい.
	while (g > 0) {
		G.push_back(g);
		cnt += sort_by_insertion(x, n, g);
		g /= 2;
	}
	std::tuple<int, std::vector<int> > ret = std::make_tuple(cnt, G);
	return ret;
}

