// 一定間隔gを空けた要素について挿入ソート
int insertionSort(int *A, int n, int g) {
    int cnt = 0;
    for (int i=g; i<n; i++) {
        int v = A[i];
        int j = i - g;
        while (j >= 0 && A[j] > v) {
            A[j+g] = A[j];
            j = j - g;
            cnt++;
        }
        A[j+g] = v;
    }
    return cnt;
}

// A: ソートされる配列
// n: 配列Aの要素数
void shellSort(int *A, int n, int *G, int *retVal) {
    int m;
    for (int i=0; i<MMAX; i++) {
        if ( SERIES(i) > n ) {
            m = i;
            break;
        }
    }
    for (int i=0; i<m; i++) {
        G[i] = SERIES(m-i-1);
    }

    int cnt = 0;
    for (int i=0; i<m; i++) {
        cnt += insertionSort( A, n, G[i] );
    }
    retVal[0] = m;
    retVal[1] = cnt;
}

