	std::ios::sync_with_stdio(false);
	int n;
	std::cin >> n;
	std::vector<int> a(n, 0);
	for (int i = 0; i < n; ++i) {
		std::cin >> a[i];
	}
	shell_sort(a, n);
	for (int i = 0; i < n; ++i) { std::cout << a[i] << '\n'; }
}

