void insertion_sort(vector<int> &a, int n, int g, int &cnt) {
    for(int i = g; i < n; ++i) {
        for(int j = i; j >= g; j -= g) {
            if(a[j] < a[j - g]) {
                swap(a[j], a[j - g]);
                cnt++;
            }
            else break;
        }
    }
}

void shell_sort(vector<int> &a, int n, int &cnt, vector<int> G) {
    for(int i = G.size() - 1; i >= 0; --i) insertion_sort(a, n, G[i], cnt);
}

