static int count = 0;
vector<int> insertionSort(vector<int> list, int gap){
    for(int i = 0; i < list.size(); i++){
        int firstValue = list[i];
        int j = i - gap;
        for(; 0 <= j && firstValue < list[j]; j -= gap){            
            list[j + gap] = list[j];
            count++;
        }
        list[j + gap] = firstValue;
    }
    return list;
} 


vector<int> createGaps(int max) {
    vector<int> gaps;
    gaps.push_back(1);
    for (int i = 0; i < max; i++){
        int gap = 3 * gaps[i] + 1;
        if (max <= gap) break;
        gaps.push_back(gap);
    }
    std::reverse(gaps.begin(), gaps.end());
    return gaps;
}

