    auto gaps = createGaps(n);
    for(int i = 0; i < gaps.size(); i++){
        result = insertionSort(result, gaps[i]);
    }
    printf("%zu\n", gaps.size());
    printList(gaps);
    printf("%d\n", count);
    for(auto each: result) {
        printf("%d\n", each);
    }
