void insertionSort(int A[], int n, int gap)
{
	for (int i = gap; i < n; i++)
	{
		// Value to insert
		int tmp = A[i];
		int j = i;
		while (j >= gap && A[j - gap] > tmp) {
			A[j] = A[j - gap];
			j -= gap;
		}
		A[j] = tmp;
	}
}

