void printArr(int N, int *arr){
    for(int i=0;i!=N;i++){
        if(i>0)cout<<" "; //隣接する要素の間に1つの空白を出力
        cout<<arr[i];
    }
    cout<<endl;
}

void printArrCol(int N, int *arr){
    for(int i=0;i!=N;i++){
        cout<<arr[i]<<endl;
    }
}

void reverseArr(int N, int *arr){
    int temp;
    for(int i=0;i!=N/2;i++){
        temp=arr[i];
        arr[i]=arr[N-i-1];
        arr[N-i-1]=temp;
    }
}

int insertionSort(int N, int *arr, int gap){
    int i, j, temp;
    int cnt=0;
    for(i=gap;i<N;i++){
        temp=arr[i];
        j=i-gap;
        while(arr[j]>temp && j>=0){
            arr[j+gap]=arr[j];
            j-=gap;
            cnt++;
        }
        arr[j+gap]=temp;
    }
    return cnt;
}

int shellSort(int N, int *arr, int m, int *gap){
    int cnt=0;

    for(int i=0;i<m;i++){
        cnt+=insertionSort(N, arr, gap[i]);
    }
    return cnt;
}

void generateGaps(int *gap, int &m, int N) {
    int h = 1;
    for (m = 0; h <= N; m++) {
        gap[m] = h;
        h = 3 * h + 1;
    }
    reverseArr(m, gap);
}

