void insertionSort(int A[], int N, int g)
{
	for (int i = g; i < N; i++)
	{
		int tmp1 = i;
		int tmp2 = i - g;
		while (tmp2 >= 0 && A[tmp2] > A[tmp1])
		{
			swap(A[tmp2], A[tmp1]);
			tmp1 = tmp2;
			tmp2 = tmp2 - g;
			cnt++;
		}
	}

}

