const int N = 1e6+9, INF = 0x3f3f3f3f;
int dt[N], cnt = 0;

void insertSort( int dt[], int n, int g ) {
    for( int i = g; i < n; ++i ) {
        int v = dt[i], j = i - g;
        while( j >= 0 && v < dt[j] ) {
            dt[j + g] = dt[j];
            j -= g;
            ++cnt;
        }
        dt[j + g] = v;
    }

}

void shellSort( int dt[], int n ) {
    vector<int> vt;
    for( int i = 0; i * 2 + 1 < n; i = i * 2 + 1 ) vt.push_back( i * 2 + 1 );
    int m = vt.size();
    if( m == 0 ) m = 1, vt.push_back( 1 );
    cout << m << '\n';
    for( int i = m - 1; i >= 0; --i ) {
        cout << vt[i] << ( i == 0 ? '\n' : ' ' );
        insertSort( dt, n, vt[i] );
    }
    cout << cnt << '\n';
}

