void insertionSort(int *array, int arraySize, int g)
{
	for (int i = g; i < arraySize; ++i)
	{
		int key = array[i];
		int j = i - g;
		while(j >= 0 && array[j] > key)
		{
			array[j + g] = array[j];
			j -= g;
			cnt++;
		}
		array[j + g] = key;
	}
}


