{
	int M = arraySize / 2;
	int G[M];
	makeG(G, M); 

	printf("%d\n", M);
	print_array(G, M, true);

	for (int i = 0; i < M; ++i)
	{
		insertionSort(array, arraySize, G[i]);
	}

}


void makeG(int *array, int M)
{
	for (int i = 0; i < M; ++i)
	{
		array[i] = M - i;
	}
}

