int InsertionSort(std::vector <int> &Sequence, int g) {
	int cnt = 0;
	for (unsigned int i = g; i < Sequence.size(); ++i) {
		int  v = Sequence[i];
		int j = i - g;
		while (j >= 0 && Sequence[j] > v) {
			Sequence[j + g] = Sequence[j];
			++cnt;
			j = j - g;
		}
		Sequence[j + g] = v;
	}
	return cnt;
}
int ShellSort(std::vector <int>& Sequence) {
	int cnt = 0;
	for (unsigned int i = 0; i < Sequence.size(); ++i) {
		if (G(Sequence.size() - i, Sequence.size()) != G(Sequence.size() - i - 1, Sequence.size())) {
			cnt += InsertionSort(Sequence, G(Sequence.size() - i - 1, Sequence.size()));
		}
	}
	return cnt;
}
