  }
  for(int i=0;i<N;i++){
    C2[i]=C1[i];
  }
  bubble(C1,N);
  selection(C2,N);
  print(C1,N);
  cout << "Stable" <<endl;
  print(C2,N);
  if(isStable(C1,C2,N)){
    cout << "Stable" <<endl;
  }
  else{
    cout << "Not stable" << endl;
  }
  return 0;
  }

