void insertionSort(int A[], const int n, const int g, int *cnt) {
    for (int i = g; i < n; ++i) {
        int tmp = A[i];
        int j   = i - g;
        while (-1 < j && tmp < A[j]) {
            // cout << A[j+g] << "<-->" << A[j] << endl;
            A[j + g] = A[j];
            j        = j - g;
            ++*cnt;
        }
        A[j + g] = tmp;
    }
}

