vector<int> insertion(vector<int> a, int g, int &cnt)
{
    for (int i = g; i < (int) a.size(); i++)
    {
        // i 番目 から (i % g) 番目までのg 個飛ばし多重スワップ
        int v = a[i];
        int j = i - g;
        while (j >= 0 && a[j] > v)
        {
            a[j + g] = a[j];
            j = j - g;
            cnt++;
        }
        a[j + g] = v;
    }

    return a;
}

