int InsertionSort_r(int arr[], int N, int range)
{

	static int counter=0;
	int compindex;
	int comp;
	int j;
	for( int i=N-2*range; i> -1; i-=range ){

		compindex=i;
		comp=arr[compindex];
		j=range;
		for( ; compindex+j<N; j+=range ){

			if(comp > arr[compindex+j])
				arr[compindex + j -range ] = arr[compindex + j];
			else
				break;

			counter++;
		}
		arr[compindex + j - range ] = comp;



	}

	return counter;



}

