int insertion_sort(std::vector<int>& ary, int shell_size) {
    int n = ary.size();
    int cnt = 0;
    for(int i = shell_size; i < n; i++) {
        int tmp_tail_val = ary[i];
        int cmp_index = i - shell_size;
        while (cmp_index >= 0 && ary[cmp_index] > tmp_tail_val) {
            ary[cmp_index + shell_size] = ary[cmp_index];
            cmp_index -= shell_size;
            cnt++;
        }
        ary[cmp_index + shell_size]  = tmp_tail_val;
    }
    return cnt;
}

int shell_sort(std::vector<int>& ary, std::vector<int> g) {
    int n = ary.size();
    int g_size = g.size();
    int cnt = 0;
    for(int i = 0; i < g_size; i++) {
        cnt += insertion_sort(ary, g[i]);
    }
    return cnt;
}

