    // ソート間隔の数列 G を作成 (g_{n+1} = 3 * g_n + 1)
    vector<int> G;
    for (int i = 0; ; i++) {
        if (i == 0) {
            G.push_back(1);
        } else {
            if (3 * G[i - 1] + 1 < n) {
                G.push_back(3 * G[i - 1] + 1);
            } else {
                break;
            }
        }
    }
    reverse(G.begin(), G.end());

    // シェルソート
    shellSort(A, G);

    // 結果を出力
    cout << G.size() << endl;
    printv<int>(G);
    cout << cnt << endl;
    printv<int>(A, "\n");

    return 0;
}

