void shellSort(vector<int>& line, const int n)
{
    vector<int> gap(MAXGAPS);
    int m = 1;
    gap[0] = m;
    int gap_cnt = 1;
    for (auto i = 1; (m = 3 * m + 1) <= n; i++) {
        gap[i] = m;
        gap_cnt++;
    }

    cout << gap_cnt << endl;
    for (auto i = gap_cnt - 1; i >=  0; i--) {
        cout << gap[i];
        if (i != 0) {
            cout << " ";
        }
    }
    cout << endl;

    for (auto i = gap_cnt - 1; i >=  0; i--) {
        insertionSort(line, n, gap[i]);
    }
}

void insertionSort(vector<int>& line, const int n, const int gap)
{
    for (auto i = gap; i < n; i++) {
        int key = line[i];

        auto j = i - gap;
        while (j >= 0 && line[j] > key) {
            line[j + gap] = line[j];
            g_cnt++;
            j -= gap;
        }

        line[j + gap] = key;
    }
}

