int
insertionSort(int* array, int num, int g)
{
    int cnt = 0;

    for (int i = 0; i < g; i++) {
        for (int j = g+i; j < num; j=j+g) {
            int targetNum = array[j];
            int k = j-g;
            for (; k >=0; k=k-g) {
                array[k+g] = array[k];
                cnt++;
                if (targetNum > array[k]) {
                    break;
                }
            }
            array[k+g] = targetNum;
            //trace(array, num);
        }
    }

    return cnt;
}

int
shellSort(int* array, int num)
{
    int orgNum = num;
    int devCnt = 0;
    while (num != 0) {
        num /= 2;
        devCnt++;
    }

    printf("%d\n", devCnt);

    int* g = createG(devCnt);

    for (int i = 0; i < devCnt; i++) {
        if (i != 0) printf(" ");
        printf("%d", g[i]);
    }
    printf("\n");

    int cnt = 0;
    for (int i = 0; i < devCnt; i++) {
        cnt = insertionSort(array, orgNum, g[i]);
    }
    return cnt;
}

int*
createG(int num)
{
    int* g = new int[num];

    for (int i = 0; i < num; i++) {
        g[i] = (int)pow(2, num-i-1);
    }

    return g;
}

