int insertionSort(int *A, int n, int g, long long cnt) {
    for (int i=g; i<n; i++) {
        int v = A[i];
        int j = i - g;

        while(j>=0 && A[j]>v) {
            A[j+g] = A[j];
            j = j - g;
            cnt++;
        }
        A[j+g] = v;
    }

    return cnt;
}


void shellSort(int *A, int n) {
    long long cnt = 0;
    int m = (int)sqrt(n/4+1);
    int G[m];

    G[0] = (int)(n/3);
    for (int i=0; i<m; i++) {
        if(i>0) G[i] = (int)(G[i-1]/3);
        if(i==m-1) G[i] = 1;
        cnt = insertionSort(A, n , G[i], cnt);
    }

    printf("%d\n", m);
    printf("%d", G[0]);
    for (int i=1; i<m; i++) printf(" %d", G[i]);
    printf("\n");
    printf("%d\n", cnt);
}


