void insertionSort(int arr[], int g) {
    FOR(i, g, n) {
        int v = arr[i];
        int j = i - g;
        while (j >= 0 && arr[j] > v) {
            arr[j+g] = arr[j];
            j -= g;
            ++cnt;
        }
        arr[j+g] = v;
    }
}

