    }
    A[j+g] = v;
  }

  return cnt;
}

void shellSort(int *A, int n){
  int i, j;
  int cnt = 0;
  int m = 0;
  int *G;

  i = n;
  while(i > 1){
    m++;
    i /= 2;
  }

  G = (int *)malloc(sizeof(int) * m);
  if(n % 2){
    G[0] = n-1;
  } else {
    G[0] = n/2;
  }
  for(i=1;i<m;i++){
    for(j=G[i-1]-1;j>0;j--){
      if(n%j == 0){
        G[i] = j;
        break;
      }
    }
  }

  // print
  printf("%d\n",m);
  for(i=0;i<m;i++){
    printf("%d",G[i]);
    if(i != m-1) printf(" ");
    else printf("\n");
  }

  for(i=0;i<m;i++){
    cnt += insertionSort(A, n, G[i]);
  }
  printf("%d\n",cnt);
}

