int insertion_sort(long *A, int N, int g)
{
    int i, cnt = 0;
    for (i = g; i < N; i++) {
        long v = A[i];
        int j = i - g;
        while (j >= 0 && A[j] > v) {
           A[j + g] = A[j];
           j = j - g;
           cnt++;
        }
        A[j + g] = v;
    }
    return cnt;
}

int shell_sort(long *A, int N, int *G, int m)
{
    int i, cnt = 0;
    for (i = m - 1; i >= 0; i--) {
       cnt += insertion_sort(A, N, G[i]);
    }
    return cnt;
}

