	int count = 0;
	for (i = g; i < max; i++) {
		int key = a[i];
		for (j = i - g; j >= 0 && a[j] > key; count++) {
			a[j + g] = a[j];
			j -= g;
		}
		a[j + g] = key;
	}
	return count;
}

