	if (max == 1) {
		g[m] = max;
		m++;
	}
	else {
		while (max / denom > 0) {
			g[m] = max / denom;
			denom *= 2;
			m++;
		}
	}

	for (i = 0; i < m; i++) {
		count += insertionSort(a, max, g[i]);
	}

	printf("%d\n", m);

