{
	int swap_count = 0;
	for(int i = g; i < n; ++i)
	{
		int v = a[i];
		int j = i - g;
		while((0 <= j) && (v < a[j]))
		{
			a[j+g] = a[j];
			j -= g;
			++swap_count;
		}
		a[j+g] = v;
	}
	return swap_count;
}

