static int32_t isPrime(int32_t n) {
    int i;
    double sq = sqrt(n);

    for ( i = 2; i <= (int)sq; i += 1 ) {
        if ( (n % i) == 0 ) {
            return 0;
        }
    }

    return 1;
}

static void printArray(const uint32_t A[], uint32_t n) {
    uint32_t i;

    for ( i = 0; i < n; i++ ) {
        printf("%u%s", A[i], i == n -1 ? "" : " ");
    }
    printf("\n");

    return;
}

static int insersionSort(uint32_t A[], uint32_t n, uint32_t g) {
    int i, j;
    uint32_t v;
    int c = 0;

    for (i = g; i < n; i++) {
        v = A[i];
        j = i - g;
        while ( (j >= 0) && A[j] > v ) {
            A[j + g] = A[j];
            j = j - g;
            c++;
        }
        A[j+g] = v;
    }

    return c;
}

