static uint32_t* makeGby3nPlusOne(uint32_t n, uint32_t* m) {
    int i;
    uint32_t* G;
    uint32_t t;

    G = malloc(sizeof(uint32_t) * 100);
    assert( G != NULL );

    G[0] = 1;
    for ( i = 1; i < 100; i++ ) {
        G[i] = G[i-1] * 3 + 1;
        if ( G[i] > n ) {
            break;
        }
    }
    *m = i;

      /* change order */
    for ( i = 0; i < *m / 2; i++ ) {
        t = G[i];
        G[i] = G[*m - i - 1];
        G[*m - i - 1] = t;
    }

    return G;
}

static inline uint32_t* makeG(uint32_t n, uint32_t* m) {
    return makeGby3nPlusOne(n, m);
}

