int insection_sort(int *A, int n, int g){
	int cnt = 0;
	int i,j,v;

	for(i=g;i<=n-1;i++){
		v = A[i];
		j = i - g;
		while( j>=0 && A[j]>v ){
			A[j+g] = A[j];
			j = j - g;
			cnt++;
		}
		A[j+g] = v;
	}

	return cnt;
}

int shell_sort(int *A, int n, int *G, int m){
	int total_cnt = 0;
	int i,cnt;

	for(i=0;i<=m-1;i++){
		cnt = insection_sort(A, n, G[i]);
		total_cnt += cnt;
	}

	return total_cnt;
}

