void InsertionSort(const long n, long line[], const int gap)
{
    long i, j;

    for (i = gap; i < n; i++) {
        long key = line[i];
        for (j = i - gap; j >= 0 && line[j] > key; j -= gap) {
            line[j + gap] = line[j];
            g_cnt++;
        }
        line[j + gap] = key;
    }
}

