void insertionSort(int R[], int n,int g,int *cnt) {
	int i, v, j;

	for (i = g; i < n; i ++) {					
		v = R[i];
		j = i - g;
		while (j >= 0 && R[j] > v) {				
			R[j + g] = R[j];
			j = j - g;
			(*cnt)++;	//()をつける！！
		}
		R[j + g] = v;
	}
}

