		printf("%d ", G[m-i-1]);
		if (i == m - 1) {
			printf("\n");
		}
	}

	for (i = 0; i < m ;i++ ) {
		insertionSort(R, n, G[m-i-1],&cnt);
	}
	printf("%d\n",cnt);
}

