void shell_sort(int_fast32_t *a, int_fast32_t n)
{
    int_fast32_t cnt = 0;
    int_fast32_t m   = log(2.0*n+1.0)/log(3.0);
    int_fast32_t g[m];
    g[m-1] = 1;
    for(int_fast32_t i=1; i<m; ++i)
        g[m-i-1] = g[m-i]*3+1;

    for(int_fast32_t i=0; i<m; ++i)
        cnt += insertion_sort(a, n, g[i]);

    printf("%"PRIdFAST32"\n", m);
