void shellSort(int A[], int n){
  int *T=(int *)malloc(sizeof(int)*n);
  while(h<=n){
    T[m] = h;
    h = h*3+1;
    m++;
  }
  int *G=(int *)malloc(sizeof(int)*m);
  for(i=0;i<=m-1;i++){
    G[i] = T[i];
  }
  for(j=m-1;j>=0;j--){
    insersionSort(A, n, G[j]);
  }
  printf("%d\n",m);
  for(i=m-1;i>=0;i--){
    if(i<m-1)printf(" ");
    printf("%d",G[i]);
  }
  free(T);
  free(G);
}

