int InsertionSort(int A[], int n, int g)
{
	int i, j;
	int tmp;
	int count = 0;

	for(i = g; i < n; i++)
	{
		j = i - g;
		while(j >= 0 && A[j] > A[i])
		{
			tmp = A[i];
			A[i] = A[j];
			A[j] = tmp;
			j = j - g;
			count++;
		}
	}
	return count;
}

