void ShellSort(const long n, long line[])
{
    int i;

    int gap[MAXGAPS];
    int m = 1;
    gap[0] = m;
    int gap_cnt = 1;
    for (i = 1; (m = 3 * m + 1) <= n && m <= 100; i++) {
        gap[i] = m;
        gap_cnt++;
    }

    printf("%d\n", gap_cnt);
    for (i = gap_cnt - 1; i >=  0; i--) {
        printf("%d", gap[i]);
        if (i != 0) {
            printf(" ");
        }
    }
    printf("\n");

    for (i = gap_cnt - 1; i >=  0; i--) {
        InsertionSort(n, line, gap[i]);
    }
}

void InsertionSort(const long n, long line[], const int gap)
{
    long i, j;

    for (i = gap; i < n; i++) {
        long key = line[i];
        for (j = i - gap; j >= 0 && line[j] > key; j -= gap) {
            line[j + gap] = line[j];
            g_cnt++;
        }
        line[j + gap] = key;
    }
}

