void insert_sort(int *A,int n,int g,int *count){
  int i=0,key=0,j=0;
  for(i=g;i<=n-1;i++){
    key=A[i];
    j=i-g;
    while(key < A[j] && j>=0){
      A[j+g]=A[j]; 
      j-=g;
      count[0]++;
    }
    A[j+g]=key;
  }
}



