void ShellSort(const int n, int line[])
{
    int i;

    int m = (n > 100)? 200: n;
    int gap[MAXGAPS];
    int gap_cnt = 0;
    for (i = 0; (m /= 2) > 0; i++) {
        gap[i] = m;
        gap_cnt++;
    }

    printf("%d\n", gap_cnt);
    for (i = 0; i < gap_cnt; i++) {
        if (i != 0) {
            printf(" ");
