    for (i = 0; i < gap_cnt; i++) {
        InsertionSort(n, line, gap[i]);
    }
}

void InsertionSort(const int n, int line[], const int gap)
{
    int i, j;

    for (i = gap; i < n; i++) {
        int key = line[i];
        for (j = i - gap; j >= 0 && line[j] > key; j -= gap) {
            line[j + gap] = line[j];
            g_cnt++;
        }
        line[j + gap] = key;
    }
}

