void shellSort(int a[], int n){
    int i, j, h, x=1;
    len = cnt = 0;
    for(i=0; x<=n; i++){
        g[i] = x;
        x = x*3+1;
        len++;
    }
    for(h=len-1; h>=0; h--){
        for(i=g[h]; i<n; i++){
            int key = a[i];
            j = i-g[h];
            while(j >= 0 && a[j] > key){
                cnt++;
                a[j+g[h]] = a[j];
                j -= g[h];
            }
            a[j+g[h]]=key;
        }
    }   
}

