int insertion_srot(int *p_arr, int size, int interval)
{
    int cnt = 0;    /* calculation amount */
    int i;
    int j;
    int locator;

    for(i = interval; i < size; i++)
    {
        locator = p_arr[i];
        j = i - interval;
        while(j >= 0 && p_arr[j] > locator)
        {
            p_arr[j + interval] = p_arr[j];
            j = j - interval;
            cnt++;
        }
        p_arr[j + interval] = locator;
    }

    return cnt;
}

void shell_sort(int *p_arr, int size)
{
   int cnt = 0;
   int interval = 1;    /* (pow(3, 0) - 1) / 2 == 0 */
   int i;
   int shell_sort_cnt;

  for(i = SHELL_SROT_CNT_MIN ;i <= SHELL_SROT_CNT_MAX; i++)
  {
      interval =  (int)((pow(3, i) - 1) / 2);
      if(interval >= size)
      {
          shell_sort_cnt = i - 1;
          printf("%d\n",shell_sort_cnt);
          break;
      }
  }


   for(i = shell_sort_cnt;;i--)
   {
       interval =  (int)((pow(3, i) - 1) / 2);
       cnt += insertion_srot(p_arr, size, interval);
       printf("%d ", interval);
       if(interval <= 1)
       {
           printf("\n");
           break;
       }
   }

   printf("%d\n", cnt);

   return;
}

