	}

	p = calculation(x);

	//printf("??????????????°_%d??¨increment??????_%d\n", x, p);

	while (x > 0){
		for (i = 0; i < array_size; i++){
			j = i;
			temp = numbers[i];
			while ((j >= calculation(x)) && (numbers[j - calculation(x)]>temp)){
				numbers[j] = numbers[j - calculation(x)];
				j = j - calculation(x);
			}
			numbers[j] = temp;
		}

		x--;
	}
}

int calculation(int value){
	int i;
	int h;
	h = 0;
	for (i = 1; i < value; i++){
		h = 3 * h + 1;
	}

	return h;
}

