{
	int i, j, target, cnt = 1;

	for(i = interval; i < length; i++) {
		j = i - interval;
		target = nums[i];

		while(j >= 0 && nums[j] > target) {
			nums[j + interval] = nums[j];
			j -= interval;
			cnt++;
		}
		nums[j + interval] = target;
	}
	return cnt;
