int insertion_sort(int size, int array[size], int gap, int count){
    int temp, j;
    for(int i = gap; i < size; i++){
        temp = array[i];
        j = i - gap;
        while(j >= 0 && array[j] > temp){
            array[j+gap] = array[j];
            j -= gap;
            if(size != 1) count++;
        }
        array[j+gap] = temp;
    }
    return count;
}

int shellSort(int size, int array[size]){
    int count = 0;
    int gap[8] = {701, 301, 132, 57, 23, 10, 4, 1}; //Ciura's Gap sequence
    for(int i = 0; i < 8; i++){
        if(size > gap[i] || gap[i] == 1){
            if(count == 0){
                printf("%d\n", 8-i);
            }
            count = insertion_sort(size, array, gap[i], count);
            if(i > 7)
                printf("%d ", gap[i]);
            else
                printf("%d\n", gap[i]);
        }
    }
    return count;
}

