void insertionSort(int R[], int n,int g,int *cnt) {
	int i, v, j;

	for (i = g; i < n; i ++) {					
		v = R[i];
		j = i - g;
		while (j >= 0 && R[j] > v) {				
			R[j + g] = R[j];
			j = j - g;
			(*cnt)++;	//()をつける！！
		}
		R[j + g] = v;
	}
}

void shellSort(int R[], int n) {
	int cnt = 0;
	int m = 0;
	int h = 0;
	int *G, i;

	G = (int*)malloc(sizeof(int)*2*n);
	while (cnt == 0) {
		h = 3 * h + 1;
		if (h > n){
			break; }
		G[m] = h;
		m++;
	}

	printf("%d\n", m);
	for (i = 0; i < m ; i++) {
		printf("%d ", G[m-i-1]);
		if (i == m - 1) {
			printf("\n");
		}
	}

	for (i = 0; i < m ;i++ ) {
		insertionSort(R, n, G[m-i-1],&cnt);
	}
	printf("%d\n",cnt);
}

