private fun shellSort(xs: List<Int>, gs: List<Int>): Pair<List<Int>, Int> {

    var cnt = 0

    fun insertionSort(xs: List<Int>, g: Int): List<Int> {
        val n = xs.size
        val ys = xs.toMutableList()

        for (i in g until n) {
            val v = ys[i]
            var j = i - g
            while (j >= 0 && ys[j] > v) {
                ys[j + g] = ys[j]
                j -= g
                cnt++
            }
            ys[j + g] = v
        }

        return ys
    }

    var ys = xs
    gs.forEach {
        ys = insertionSort(ys, it)
    }

    return Pair(ys, cnt)
}

