		interval = g;
		sort();
	}
	@Override
	public void sort(){
		for(int i=interval; i<this.length;i++){
			comparable key = sortList.get(i);
			int j=i-interval;
			for(; j>=0 ;){
				if(sortList.get(j).compValue()<key.compValue())
					break;
				sortList.set(j+interval,sortList.get(j));
				j-=interval;
				count++;
			}
			sortList.set(j+interval, key);
		}
	}
