        for(int i=g;i<n;i++){
            int v = A[i];
            int j = i - g;
            // 挿入先が見つかるまでループ
            // 挿入するため、見ていった要素を一個ずつ後方へズラす。
            while(j >=0 && A[j] > v){
                A[j+g] = A[j];
                j = j -g;
                cnt++;
            }
            // 見つけた挿入場所へ挿入。
            A[j+g] = v;
        }
    }

