        cnt = 0;
        int i, m;
        int G[] = new int[100];
        if(n < 3){
            G[0] = n;
            G[1] = n-1;
            G[2] = 1;
            m = n;
        }else{
            int j = 0;
            for(i=1;i<n;i++){
                if(n/i == 0){
                    G[i-1] = 1;
                    break;
                }
                G[i-1] = n/i;
