    }

    private static int[] insertionSort(int[] a, int gap) {
        for (int i = gap; i < a.length; i++) {
            int target = a[i];
            int j = i - gap;
            while (j >= 0 && a[j] > target) {
                a[j + gap] = a[j];
                j -= gap;
                count++;
            }
            a[j + gap] = target;
        }
        return a;
    }
