	/**
	 *
	 * @param array
	 * @param number
	 * @param g
	 * @param cnt
	 * @return
	 */
	private static int insertionSort(int[] array, int number, int g, int cnt) {

		// gからn-1まで
		int temp = 0;
		for (int i = g, j = 0; i < number; i++) {
			temp = array[i];
			j = i - g;

			// 自分より大きいやつが見つかるまで
			while (j >= 0 && array[j] > temp) {
				array[j + g] = array[j];
				j = j - g;
					cnt++;
			}
			array[j + g] = temp;
		}
		return cnt;
	}

	/**
	 *
	 * @param array
	 * @param number
	 */
	private static void shellSort(int[] array, int number) {

		// Gの準備
		List<Integer> G = new ArrayList<>();
		int g = 0;
		while (true) {
			// 3g+1
			g = (3 * g) + 1;
			if (g > number) {
				break;
			}
			G.add(g);
		}

		// 結果出力
		System.out.println(G.size());
		for (int i = G.size() - 1; i >= 0; i--) {
			System.out.print(G.get(i) + (i == 0 ? "\n" : " "));
		}

		int cnt = 0;
		for (int i = G.size() - 1; i >= 0 ; i--) {
			cnt = insertionSort(array, number, G.get(i), cnt);
		}

		// 結果出力
		System.out.println(cnt);
	}

