	/**
	 * 挿入ソート
	 * 
	 * @param A：オリジンの配列
	 * @param N：要素の個数
	 */
	public static void insertionSort(int[] A, int N, int g) {

		for (int i = g; i < N; i++) {
			int v = A[i]; // 1枚取り出す
			int j = i - g;
			while (j >= 0 && A[j] > v) {// 取り出した一枚より前の方に持っていたカードと比較
				A[j + g] = A[j];
				j = j - g;
				cnt++;
			}
			A[j + g] = v;

		}

	}

	/**
	 * シェルソート
	 * @param A オリジンの配列
	 * @param N：要素の個数
	 */
	public static void shellSort(int[] A, int N) {
		for (int i = 1;; i = i * 3 + 1) {
			if (i > N) {
				break;
			}
			G[m] = i;		
			m++;
		}
		for (int i = m - 1; i >= 0; i--) {
			insertionSort(A, N, G[i]);
		}
	}

}

