        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int [] L = new int[N];
        for(int i=0;i<N;i++) L[i] = sc.nextInt();
        int m=0,cnt =0;
        int g = 1,g2=1;
        while(g2<=N){
            g*=3;
            g2+=g;
            m++;
        }
        int G [] = new int [m];
        G[m-1]=1;
        g = 1;
        for(int i=1;i<m;i++){
            g*=3;
            G[m-i-1]=G[m-i]+g;
        }
        for(int i=0;i<m;i++) cnt = insertion_sort(L,N,G[i],cnt);
