        for(int i=0;i<m;i++){
            if(i!=m-1) System.out.print(G[i]+" ");
            else  System.out.println(G[i]);
        }
        System.out.println(cnt);
        for(int i:L) System.out.println(i);
    }
    public static int insertion_sort(int [] L,int N,int g,int cnt){
        for(int i=g;i<N;i++){
            int v = L[i];
            int j = i-g;
            while(j>=0&&L[j]>v){
                L[j+g]=L[j];
                j = j-g;
                cnt++;
            }
            L[j+g]=v;
        }
        return cnt;
    }
}

