import java.util.*;

public class Main{
	private static final Scanner scan = new Scanner(System.in);
	static int N;

	public static void main(String[] args){

		int n = scan.nextInt();
		int[] arr = new int[n];
		for(int i = 0; i < n; i++){
			arr[i] = scan.nextInt();
		}

		shellSort(arr, n);
	}

	static int insertSort(int[] a, int n, int g, int cnt){
		int v, j;
		for(int i = g; i < n; i++){
			v = a[i];
			j = i - g;
			while(j >= 0 && a[j] > v){
				a[j+g] = a[j];
				j = j - g;
				cnt++;
			}
			a[j+g] = v;
		}
		return cnt;
	}

	static void shellSort(int[] a, int n){
		int cnt, m, count, gCheck;
		cnt = 0;
		count = 0;
		gCheck = 1;

		while(n > gCheck){
			gCheck = gCheck * 2 + 1;
			count++;
		}
		if(count == 0)
			count = 1;
		m = count;
		int[] g = new int[m];
		g[m-1] = 1;

		for(int i = 1; i < m; i++){
			g[m-i-1] = g[m-i] * 2 + 1;
		}

		for(int i = 0; i < m; i++){
			cnt = insertSort(a, n, g[i], cnt);
		}

		System.out.println(m);
		for(int i = 0; i < m; i++){
			System.out.printf(i != m-1? "%d " : "%d\n", g[i]);
		}
		System.out.printf("%d\n", cnt);
		for(int i = 0; i < n; i++){
			System.out.printf("%d\n", a[i]);
		}
	}
}

import java.util.Scanner;

class Main {
	public static void main(String args[]) {
		Scanner scanner = new Scanner(System.in);
		int  num = scanner.nextInt();//要素数
		int array[] = new int[num];

		for(int i = 0; i < num; i ++ ){
			array[i] = scanner.nextInt();
		}

		shellSort(array, num);

		scanner.close();
	}

	public static int insertionSort( int[] array, int num, int g ,int count){ // N個の要素を含む0-オリジンの配列A
		int sub;
		int comp = 0;
		int i;

		for( i = 1; i <=  num - 1; i ++ ){
			sub = array[i];
			comp = i - g;
			while( -1 < comp && sub < array[comp] ){
				array[comp + g] = array[comp];
				comp = comp - g;
				count ++;
			}
			array[comp + 1] = sub;

		}
		return count;
	}

	public static void shellSort(int[] array, int num){
		int cnt = 0;
		int m = 0;
		int[] arrayG = new int[100];
		for( int i = 0; i < 100; i ++ ){
			if( i == 0 ){
				arrayG[i] = num / 2 + 1;
			}else{
				arrayG[i] = arrayG[i-1] / 2 - 1;
			}

			if( arrayG[i] < 0 ){
				arrayG[i - 1] = 1;
				arrayG[i] = 0;
				m = i;

				break;
			}

		}
		for( int i = 0; i < m; ++i ){
			insertionSort(array, num, arrayG[i], cnt);
		}


		System.out.println(m);
		for(int cou = 0; cou < m; cou ++ ){
			System.out.print(array[cou]);
			if( cou == num - 1) {
			System.out.print("\n");
			}else {
				System.out.print(" ");
			}
		}
		System.out.println(cnt);
		for(int cou = 0; cou < num; cou ++ ){
			System.out.println(array[cou]);
		}
	}

}

