		long v;
		int j;
		for (int i = g; i < array.length; i++) {
			v = array[i];
			j = i - g;
			while (j >= 0 && array[j] > v) {
				array[j + g] = array[j];
				j -= g;
				count++;
			}
			array[j + g] = v;
		}
		return count;
	}

