			for (int j = m; j > 0; j--) {
				distanceList[j] = distanceList[j - 1];
			}
			distanceList[0] = i;
			m++;
		}
		if (m == 0) {
			distanceList[0] = 1;
			m = 1;
		}

		for (int i = 0; i < distanceList.length; i++) {
			inssertionSort(numList, count, distanceList[i], flag);
