            int j = i - gap;
            while (j >= 0 && array[j] > value) {
                array[j + gap] = array[j];
                j -= gap;
                count++;
            }
            array[j + gap] = value;
        }
    }

    private static void shellSort(int[] array, int size) {
        int m = 0;
