        // ソートしながら結果出力
        int cnt = 0;
        stringBuilder.append(gSize);
        stringBuilder.append('\n');
        for (int i = gSize - 1; i >= 0 ; i--) {
            stringBuilder.append(G[i]);
            if (i != 0)
                stringBuilder.append(' ');
            cnt += insertionSort(array, number, G[i]);
        }
        G = null;

        // 結果出力
        stringBuilder.append('\n');
        stringBuilder.append(cnt);
        stringBuilder.append('\n');
    }
}

