		int sub;
		int comp = 0;
		int i;

		for( i = 1; i <=  num - 1; i ++ ){
			sub = array[i];
			comp = i - g;
			while( -1 < comp && sub < array[comp] ){
				array[comp + g] = array[comp];
				comp = comp - g;
				count ++;
			}
			array[comp + g] = sub;

		}
