                j = j - g;
                counter++;
            }

            b[j + g] = v;
        }

        return counter;
    }

    public static void shellSort(int[] b, int n) {
        int counter = 0;
        int m = 0;
        int g[] = new int[100];

        for (int i = 1; i <= n; i=i*3+1) {
            g[m] = i;
            m++;
        }

        System.out.println(m);

        m--;

        for (int i = m; i >= 0; i--) {
            counter += insertionSort(b, n, g[i]);

            if (i == 0) {
                System.out.printf(" %d", g[i]);
            } else {
                System.out.printf("%d", g[i]);
            }
        }

        System.out.println("\n" + counter);

        for (int i = 0; i < n; i++) {
            System.out.println(b[i]);
        }
    }
}

