			int j = i - g;
			while(j >= 0 && arr[j] > key) {
				arr[j + g] = arr[j];
				j -= g;
				count++;
			}
			arr[j + g] = key;
		}
		return count;

	}
	public static int shellSort(int[] arr, int n, List<Integer> list) {
		int count = 0;
		for(int i = 0; i < list.size(); i++) {
			count += insertionSort(arr, n, list.get(i));
		}
		return count;
	}
