			}
			array[j+interval] = key;
		}
	}

	public static void shellSort(int[] array, int length) {
		List<Integer> intervals = new ArrayList<Integer>();
		for (int i=0; i<length; ) {
			i = 3*i + 1;
			intervals.add(i);
		}

		int size = intervals.size();

