class Solve {
	public final int n;
	public final int[] A;

	public Solve(final int n, final int[] A)
	{
		this.n = n;
		this.A = A;
	}

	public void solve()
	{
		int count = 0;

		int[] G = { 1, 4, 13, 40, 121, 364, 1093, 3280, 9841, 29524, 88573, 265720, 797161 };

		int[] sorted = new int[n];

		for(int i=0; i < n; i++) sorted[i] = A[i];

		for(int i=G.length-1; i >= 0; i--)
		{
			count = insertionSort(sorted, n, G[i], count);
		}

		int start = G.length-1;
		for(; start >= 0 && n < G[start]; start--);

		System.out.println(start + 1);

		for(int i=start; i >= 0; i--)
		{
			if(i < start) System.out.print(" ");
			System.out.print(G[i]);
		}

		System.out.println("");
		System.out.println(count);

		for(int i=0; i < n; i++) System.out.println(sorted[i]);
	}

	private int insertionSort(int[] A, final int n, final int g, int count)
	{
		for(int i=g; i < n; i++)
		{
			int v = A[i];
			int j = i - g;

			while(j >= 0 && A[j] > v)
			{
				A[j + g] = A[j];
				j = j - g;
				count++;
			}

			A[j + g] = v;
		}

		return count;
	}
}
class ContestScanner {
	BufferedReader reader;
	String[] line;
	int index;
	public ContestScanner() {
		reader = new BufferedReader(new InputStreamReader(System.in));
	}

	public ContestScanner(String filename) throws FileNotFoundException {
		reader = new BufferedReader(new InputStreamReader(new FileInputStream(filename)));
	}

	public String nextToken() throws IOException {
		if(line == null || index >= line.length)
		{
			line = reader.readLine().trim().split(" ");
			index = 0;
		}

		return line[index++];
	}

	public String next() throws IOException {
		return nextToken();
	}

	public String readLine() throws IOException {
		line = null;
		index = 0;

		return reader.readLine();
	}

	public int nextInt() throws IOException, NumberFormatException {
		return Integer.parseInt(nextToken());
	}

	public long nextLong() throws IOException, NumberFormatException {
		return Long.parseLong(nextToken());
	}

	public double nextDouble() throws IOException, NumberFormatException {
		return Double.parseDouble(nextToken());
	}

	public int[] nextIntArray(int N) throws IOException, NumberFormatException {
		int[] result = new int[N];

		for(int i=0; i < N; i++) result[i] = nextInt();

		return result;
	}

	public long[] nextLongArray(int N) throws IOException, NumberFormatException {
		long[] result = new long[N];

		for(int i=0; i < N; i++) result[i] = nextLong();

		return result;
	}

	public double[] nexDoubleArray(int N) throws IOException, NumberFormatException {
		double[] result = new double[N];

		for(int i=0; i < N; i++) result[i] = nextDouble();

		return result;
	}
}

