		Scanner scanner = new Scanner(System.in);
		int  num = scanner.nextInt();//要素数
		int array[] = new int[num*2];

		for(int i = 0; i < num; i ++ ){
			array[i] = scanner.nextInt();
		}

		shellSort(array, num);

		scanner.close();
	}

	public static int insertionSort( int[] array, int num, int g ,int count){ // N個の要素を含む0-オリジンの配列A
		int sub;
		int comp = 0;
		int i;

		for( i = 1; i <=  num - 1; i ++ ){
			sub = array[i];
			comp = i - g;
			while( -1 < comp && sub < array[comp] ){
				array[comp + g] = array[comp];
				comp = comp - g;
				count ++;
			}
			array[comp + g] = sub;

		}
		return count;
	}

	public static void shellSort(int[] array, int num){
		int cnt = 0;
		int m = 0;
		int[] arrayG = new int[100];
		for( int i = 0; i < 100; i ++ ){
			if( i == 0 ){
				arrayG[i] = num / 2 + 1;
			}else{
				arrayG[i] = arrayG[i-1] / 2 - 1;
			}

			if( arrayG[i] < 0 ){
				arrayG[i - 1] = 1;
				arrayG[i] = 0;
				m = i;

				break;
			}

		}
		for( int i = 0; i < m; ++i ){
			cnt = insertionSort(array, num, arrayG[i], cnt);
		}


		System.out.println(m);
		for(int cou = 0; cou < m; cou ++ ){
			System.out.print(arrayG[cou]);
			if( cou <= num - 1) {
			System.out.print("\n");
			}else {
				System.out.print(" ");
			}
		}
		System.out.println(cnt);
		for(int cou = 0; cou < num; cou ++ ){
			System.out.println(array[cou]);
		}
	}

}

