	{
		int i = 1;
		while(i < n) {
			this.G.add(i);
			i = i * 3 + 1;
		}

		for (i = this.G.size() - 1; i >= 0; i--) {
			insertionSort(a, n, this.G.get(i));
		}

		return a;
	}

	private int[] insertionSort(int[] a, int n, int g)
	{
		for (int i = g; i < n; i++) {
			int v = a[i];
			int j = i - g;
			while (j >= 0 && a[j] > v) {
				a[j+g] = a[j];
				j = j - g;
				this.cnt++;
			}
			a[j+g] = v;
		}

		return a;
	}
}

