	public static void revPrintArrayList(ArrayList<Integer> a){
		int n = a.size();
		for(int i = n-1; i >= 0; --i){
			System.out.print(a.get(i).intValue());
			if(i != 0)  System.out.print(" ");
		}
		System.out.println();
	}

