		int n = a.length, ret = 0;
		for(int i = g; i < n; ++i){
			int instnum = a[i], j;
			for(j = i - g; j >= 0 && a[j] > instnum; j -= g){
				a[j+g] = a[j]; ++ret;
			}
			a[j+g] = instnum;
		}
		return ret;
	}

	public static long shellSort(int[] a){
		long cnt = 0;
		int n = a.length;
		for(int h = 1;;){
			if(h > n) break;
			G.add(h);
			h = 3 * h + 1;
		}

		for(int i = G.size()-1; i >= 0; --i){
			cnt += insertionSort(a, G.get(i));
		}
		return cnt;
	}
}

