		int count = 0;
		for(int i = g; i < array.length; i++){
			int v = array[i];
			int j = i - g;
			while(0 <= j && v < array[j]){
				array[j+g] = array[j];
				j -= g;
				count++;
			}
			array[j+g] = v;
		}

		return count;
	}

	public static void shellSort(int[] array){
		int count = 0;

		List<Integer> gList = new ArrayList<>();
		for(int i = 1; ; i++){
			int g = (int)((Math.pow(3, i) - 1) / 2);
			if(g <= array.length){
				gList.add(g);
			}else{
				break;
			}
		}
		Collections.reverse(gList);
