				list.add(i);
				i = 3 * 1 + 1;
			} while(divisor > 0 && i < n / divisor);
			for(int j = list.size() - 1; j >= 0; j--) {
				count += insertionSort(arr, n, list.get(j));
			}
			if(count <= Math.pow(n, 1.5)) {
				return count;
			} else {
				divisor--;
			}
		}
	}

