      int[] arr = new int[n];
      for (int i = 0; i < n; i++) {
        arr[i] = sc.nextInt();
      }

      cnt = 0;
      shellSort(arr);

      StringBuilder sb = new StringBuilder();
      sb.append(g.size() + "\n");
      for (int i = g.size() - 1; i >= 0; i--) {
        sb.append(g.get(i));
        if (i != 0) sb.append(' ');
      }
