    // via https://stackoverflow.com/questions/2539545/fastest-gap-sequence-for-shell-sort
    int[] optimal = {1, 4, 10, 23, 57, 132, 301, 701, 1750};
    List<Integer> G = new ArrayList<Integer>();
    int i = 0;
    int num = optimal[i];
    G.add(num);
    while (num < n) {
      i++;
      if (i < optimal.length) {
        num = optimal[i];
      } else {
        num = (int)(num * 2.25);
      }
      if (num < n)
