        B[1] = 1;
        long max = 0;
        int i = 2;
        while(max < a){
            B[i] = B[i-1] + B[i-2];
            C[i-2] = (long)Math.pow(B[i-1], 1 + Math.sqrt(5));
            max = C[i-2];
            i++;
        }
        int[] D = new int[i-3];
        for(int j = 0; j < i-3; j++){
            D[j] = (int)C[i-4-j];
        }
        return D;
