			while (j >= 0 && array[j] > temp) {
				array[j + g] = array[j];
				j = j - g;
				cnt++;
			}
			array[j + g] = temp;
		}
		return cnt;
	}

	/**
	 *
	 * @param array
	 * @param number
	 */
	private static void shellSort (int[] array, int number) {

		// Gの準備
		int[] G = new int[number];

		int g = 0;
		int gSize = 0;
		for (int i = 0; i < number; i++) {
			// 3g + 1
			g = (3 * g) + 1;
			if (g > number) {
				G[i] = -1;
				break;
			} else {
				G[i] = g;
				gSize++;
			}
		}

		// ソートしながら結果出力
		int cnt = 0;
		System.out.println(gSize);
		for (int i = gSize - 1; i >= 0 ; i--) {
			System.out.print(G[i] + (i == 0 ? "\n" : " "));
			cnt = insertionSort(array, number, G[i], cnt, 0);
		}
		G = null;

		// 結果出力
		System.out.println(cnt);
	}

	/**
	 * ソート結果の出力をする。
	 * @param sortedArray ソートされた配列
	 */
	private static void printSortResult(int[] sortedArray) {
		for (int i = 0; i < sortedArray.length; i++) {
			System.out.println(sortedArray[i]);
		}
	}

}

