class ShellSort {
	List<Integer> g;
	int[] preserve;

	ShellSort(int[] arr) {
		preserve = new int[arr.length];
		for(int i = 0; i < arr.length; i++) {
			preserve[i] = arr[i];
		}
	}

	public int insertionSort(int[] arr, int n, int g) {
		int count = 0;
		for(int i = g; i < n; i++) {
			int key = arr[i];
			int j = i - g;
			while(j >= 0 && arr[j] > key) {
				arr[j + g] = arr[j];
				j -= g;
				count++;
			}
			arr[j + g] = key;
		}
		return count;
	}
	public int shellSort(int[] arr, int n, List<Integer> list) {
		int e = 1;
		do {
			list.add(0, e);
			e = 3 * e + 1;
		} while(e <= n / 9);
		int count = 0;
		while(true) {
			for(int i = 0; i < list.size(); i++) {
				count += insertionSort(arr, n, list.get(i));
			}
			if(count < Math.ceil(Math.pow(n, 1.5))) {
				return count;
			} else {
				count = 0;
				e = 3 * e + 1;
				list.add(0, e);
				for(int i = 0; i < n; i++) {
					arr[i] = preserve[i];
				}
			}
		}
	}

}

