		for (int i=interval; i<length; i++) {
			int key = array[i];
			int j = i - interval;
			while (j>=0 && key<array[j]) {
				array[j+interval] = array[j];
				j -= interval;
				cnt++;
			}
			array[j+interval] = key;
		}
	}

