            int[] arr = new int[N];
            for (int i = 0; i < N; i++)
            {
                arr[i] = int.Parse(Console.ReadLine());
            }

            shellSort(arr, N);

            for (int i = 0; i < N; i++)
            {
                Console.WriteLine(arr[i]);
            }

        }

        public static int insertionSort(int[] arr, int n, int g)
        {
            int count = 0;
            for (int i = g; i < n; i++)
            {
                int tmp = arr[i];
                int j = i - g;
                while (j >= 0 && arr[j] > tmp)
                {
                    arr[j + g] = arr[j];
                    j = j - g;
                    count++;
                }
                arr[j + g] = tmp;
            }
            return count;
        }

        public static void shellSort(int[] arr, int n)
        {
            int count = 0;
            int m = 1;
            int tmp = 1;
            for (int i = 1; i < 100; i++)
            {
                tmp = tmp * 3;
                if (tmp > 2 * n + 1)
                {
                    m = i - 1;
                    break;
                }    
            }

            int[] G = new int[m];
            G[0] = 1;
            for (int i = 1; i < m; i++)
            {
                G[i] = 3 * G[i - 1] + 1;
            }

            for (int i = m - 1; i >= 0; i--)
            {
                count += insertionSort(arr, n, G[i]);
            }

            string output = ArrayJoin(G);
            Console.WriteLine(m);
            Console.WriteLine(output);
            Console.WriteLine(count);
        }

        public static string ArrayJoin(int[] arr)
        {
            StringBuilder sb = new StringBuilder();
            for (int i = arr.Length - 1; i >= 0; i--)
            {
                if (sb.Length > 0)
                {
                    sb.Append(" ");
                }
                sb.Append(arr[i]);
            }
            return sb.ToString();
        }
    }
