    static List<int> G=new List<int>();
    static int InsertionSort(int g){
        var cnt=0;
        for(var i=g; i<A.Length; i++){
            var v=A[i];
            var j=i-g;
            while(j>=0 && A[j]>v){
                A[j+g]=A[j];
                j=j-g;
                cnt++;
            }
            A[j+g]=v;
        }
        return cnt;
    }

    static int ShellSort(){
        var cnt=0;
        for(var g=1; g<=A.Length;){
            G.Add(g);
            g=3*g+1;
        }
        G.Reverse();
        foreach(var g in G){
            cnt+=InsertionSort(g);
        }
        return cnt;
    }

