            for (int i=0; i<num; i++)
            {
                input[i] = int.Parse(Console.ReadLine());
            }

            shellsort(input, num);
            output_result(input);

        }

        static void shellsort(int[] a, int n)
        {
            int cnt = 0;
            int m = 0;
            int h = 0;

            for (int h_tmp=0; h_tmp < n; h_tmp = h_tmp * 3 + 1)
            {
                h = h_tmp;
                m++;
            }
            output_m(m);

            int[] g = new int[m];
            int m_tmp = 0;
            for (int h_tmp=h; h_tmp>0; h_tmp /= 3)
            {
                g[m_tmp] = h_tmp;
                m_tmp++;
            }
            output_h(g);


            for (int i=0; i<m; i++)
            {
                cnt += insertionsort(a, n, g[i]);
            }

            output_cnt(cnt);

        }

        static int insertionsort(int[] a, int n, int g)
        {
            int count = 0;
            int tmp = 0;
            for (int i = g; i < n; i++)
            {
                int value = a[i];
                int j = i - g;

                while (j >= 0 && a[j] > value)
                {
                    tmp = a[j + g];
                    a[j + g] = a[j];
                    a[j] = tmp;
                    j = j - g;
                    count++;
                }
            }
            return count;
        }

        static void output_m(int m)
        {
            Console.WriteLine(m);
        }

        static void output_h(int[] g)
        {
            for (int i=0; i<g.Length; i++)
            {
                if (i != g.Length-1)
                {
                    Console.Write("{0} ", g[i]);
                }
                else
                {
                    Console.Write(g[i]);
                    Console.WriteLine();
                }
            }
        }

        static void output_cnt(int cnt)
        {
            Console.WriteLine(cnt);
        }

        static void output_result(int[] result)
        {
            for (int i=0; i<result.Length; i++)
            {
                Console.WriteLine(result[i]);
            }
