            for (int i=0;i<n;i++)
            {
                num[i] = int.Parse(Console.ReadLine());
            }

            shellSort(num, n);
        }

        static void shellSort(int [] num, int n)
        {
            int cnt = 0;
            int m = 2;
            int[] G = { 4, 1 };

            Console.WriteLine(m);

            for (int i=0;i<m;i++)
            {
                insertionSort(num, n, G[i], ref cnt);
                Console.Write((i==0?"":" ")+G[i]);
            }
            Console.WriteLine();
            Console.WriteLine(cnt);
            for(int j=0; j<n;j++)
            {
                Console.WriteLine(num[j]);
            }
        }

        static void insertionSort(int[] num, int n, int g, ref int cnt)
        {
            for(int i=g;i<n;i++)
            {
                int key = num[i];
                int j = i - g;
                while(j>=0&&num[j]>key)
                {
                    num[j + g] = num[j];
                    j = j - g;
                    cnt++;
                }
                num[j + g] = key;
            }
