				if (i == m - 1) Console.Write("\n");
				else Console.Write(" ");
			}
			Console.WriteLine(cnt);
		}

		public static void Insertion(int[] A, int n, int g, ref int cnt)
		{
			for (int i = g; i < n; i++)
			{
				int v = A[i];
				int j = i - g;
				while (j >= 0 && A[j] > v)
				{
					A[j + g] = A[j];
					j = j - g;
					cnt++;
				}
				A[j + g] = v;
			}
		}

