namespace ALDS1_2_D
{
    class Program
    {
        static int counter;
        static StringBuilder sb = new StringBuilder();

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            int[] numbers = new int[n];

            for (int i = 0; i < n; i++)
                numbers[i] = int.Parse(Console.ReadLine());

            ShellSort(numbers, n);

            foreach (var num in numbers)
            {
                sb.AppendLine(num.ToString());
            }
            Console.WriteLine(sb);
        }
        static void InsertionSort(int[] numbers, int n, int g) //挿入ソート
        {
            for (int i = g; i < n; i++)
            {
                int v = numbers[i];
                int j = i - g;
                while (j >= 0 && numbers[j] > v)
                {
                    numbers[j + g] = numbers[j];
                    j = j - g;
                    counter++;
                }
                numbers[j + g] = v;
            }
        }

        static void ShellSort(int[] numbers, int n)
        {
            counter = 0;
            int h = 1;
            int m = 0;

            do
            {
                m++;
                h = h * 3 + 1;
            } while (h < n);

            int[] G = new int[m];

            for (int i = m - 1, x = 0; i >= 0; i--)
            {
                x = x * 3 + 1;
                G[i] = x;
            }

            for (int i = 0; i < m; i++)
            {
                InsertionSort(numbers, n, G[i]);
            }

            sb.AppendLine(m.ToString());
            sb.AppendLine(string.Join(" ", Array.ConvertAll(G, g => g.ToString())));
            sb.AppendLine(counter.ToString());
        }

    }
}

