		}

		void Calc() {
			var N = int.Parse(Input);	// Number of elements
			var A = new int[N];         // Array : N elements
            for (int i = 0; i < N; i++)
                A[i] = int.Parse(Input);
			shellSort(A, N);
		}

		String Input {
			get {
				return Console.ReadLine();
			}
		}

		void Output(String str) {
			Console.WriteLine(str);
		}

        int[] selectionSort(int[] A, int N, int g, ref int count) {
Output("+++"+g+"");
            for(int i = g; i < N; i++) {
				int target = A[i];
				int j = i - g;
				while(j >= 0 && target < A[j]) {
					A[j+g] = A[j];
                    count++;
                    j -= g;
                }
				A[j+g] = target;
			}
            //Output(A.Select(s => s.ToString())
            //        .Aggregate((s, t) => s + " " + t));
            return A;
        }

        void shellSort(int[] A, int N) {
            int cnt = 0;
            var GList = new List<int>() {1};
