    class Progaram
    {
        private static int[] I_Sort(int[] ca, int n)
        {
            var c = new int[ca.Length];
            ca.CopyTo(c, 0);
            for (int i = n; i < c.Length; i++)
            {
                var v = c[i];
                var j = i - n;
                while (j >= 0 && c[j] > v)
                {
                    c[j+n] = c[j];
                    j -= n;
                    cnt++;                        
                }
                c[j+n] = v;
            }
            return c;
        }

        static int cnt = 0;
        static List<int> g = new List<int>();
        private static int[] Shell_Sort(int[] ca)
        {
            var m = 1;
            var n = ca.Length / 9;
            while (m <= n) m = m * 3 + 1;
            for (;m > 0; m /= 3)
            {
                ca = I_Sort(ca, m);
                g.Add(m);
            }        
            return ca;
        }

        static void Main()
        {
            Console.ReadLine();
            var ls = new List<int>();
            string s;
            while ((s = Console.ReadLine()) != null)
                ls.Add(int.Parse(s));
            var array = Shell_Sort(ls.ToArray());
            Console.WriteLine("{0}\n{1}", g.Count, string.Join(" ", g.Select(e => e.ToString())));
            Console.WriteLine("{0}", cnt);
            foreach (var v in array)
