		public static void Main(string[] args)
		{
			int n = int.Parse(Console.ReadLine());
			int[] A = new int[n];
			for (int i = 0; i < n; i++)
			{
				A[i] = int.Parse(Console.ReadLine());
			}
			cnt = 0;
			int m = (int)Math.Pow(n, (double)1 / 3);
			int[] G = new int[m];
			G[0] = 1;
			if(m - 1 != 0)
				G[m - 1] = n;
			for (int i = 1; i < m - 1; i++)
			{
				G[m - i - 1] = Math.Max(1, G[m - i] / 3);
			}
			for (int i = 0; i < m; i++)
			{
				InsertionSort(A, n, G[i]);
			}
			Console.WriteLine(m);
			for (int i = 0; i < m; i++)
			{
				Console.Write(G[i]);
				Console.Write(i != m - 1 ? " " : "\n");
			}
			Console.WriteLine(cnt);
			for (int i = 0; i < A.Length; i++)
			{
				Console.WriteLine(A[i]);
			}

		}

		public static void InsertionSort(int[] A, int n, int g)
		{
			for (int i = g; i < n; i++)
			{
				int v = A[i];
				int j = i - g;
				while (j >= 0 && A[j] > v)
				{
					A[j + g] = A[j];
					j = j - g;
					cnt++;
				}
				A[j + g] = v;
			}
		}
	}
}

