namespace ALDS1_2_D {
    class Problem {
        private List<int> _nums, _intervalList;
        private int _len, _cnt;

        public Problem(List<int> nums, int len) {
            _nums = nums;
            _len = len;
        }

        public void Run() {
            ShellSort();

            StringBuilder sb = new StringBuilder();
            sb.AppendLine(_intervalList.Count.ToString());
            sb.AppendLine(ListToString(_intervalList));
            sb.AppendLine(_cnt.ToString());
            _nums.ForEach(n => sb.AppendLine(n.ToString()));
            Console.Write(sb);
        }

        private void ShellSort() {
            _cnt = 0;
            MakeIntervalList();
            _intervalList.ForEach(n => InsertionSort(n));
        }

        private void InsertionSort(int g) {
            for (int i = g; i < _len; i++) {
                int v = _nums[i];
                int j = i - g;
                while (j >= 0 && _nums[j] > v) {
                    _nums[j + g] = _nums[j];
                    j -= g;
                    _cnt++;
                }
                _nums[j + g] = v;
            }
        }

        private void MakeIntervalList() {
            _intervalList = new List<int>();
            for (int h = 1; h <= _len; h = 3 * h + 1) {
                _intervalList.Insert(0, h);
            }
        }

        private string ListToString(List<int> list) {
            StringBuilder sb = new StringBuilder();
            list.ForEach(n => sb.AppendFormat(" {0}", n));
            return sb.ToString().TrimStart();
        }
    }

    class Program {
        static void Main(string[] args) {
            int n = int.Parse(Console.ReadLine());
            List<int> A = new List<int>();
            for(int i = 0; i < n; i++) {
                A.Add(int.Parse(Console.ReadLine()));
            }

            Problem p = new Problem(A, n);
            p.Run();
        }
    }
}

