        {
            int count = 0;
            int tmp = 0;
            for (int i = g; i < n; i++)
            {
                int value = a[i];
                int j = i - g;

                while (j >= 0 && a[j] > value)
                {
                    tmp = a[j + g];
                    a[j + g] = a[j];
                    a[j] = tmp;
                    j = j - g;
                    count++;
