        {
            // スタートはgap。0に向かって間隔ごとに比較する
            for (int i = gap; i < N; i++)
            {
                int v = A[i];
                int j = i - gap;
                // vより大きいものはずらす
                while (j >= 0 && A[j] > v)
                {
                    A[j + gap] = A[j];
                    j -= gap;
                    count++;
                }
                A[j + gap] = v;
            }
        }

        static void ShellSort(int[] A, int N)
        {
            // 挿入ソートの間隔の数列を作成
            for (int h = 1; h <= N; h = 3 * h + 1)
            {
                G.Add(h);
            }
            G.Reverse();

            // 間隔を使って挿入ソート
            for (int i = 0; i < G.Count; i++)
            {
                InsertionSort(A, N, G[i]);
            }
        }

