namespace ALDS1_2_D {
	class Program {
		public Program() {}

		public static void Main() {
			new Program().Calc();
		}

		void Calc() {
			var N = int.Parse(Input);	// Number of elements
			var A = new int[N];         // Array : N elements
            for (int i = 0; i < N; i++)
                A[i] = int.Parse(Input);
			shellSort(A, N);
		}

		String Input {
			get {
				return Console.ReadLine();
			}
		}

		void Output(String str) {
			Console.WriteLine(str);
		}

        int[] selectionSort(int[] A, int N, int g, ref int count) {
            for(int i = g; i < N; i++) {
				int target = A[i];
				int j = i - g;
				while(j >= 0 && target < A[j]) {
					A[j+g] = A[j];
                    count++;
                    j -= g;
                }
				A[j+g] = target;
			}
            //Output(A.Select(s => s.ToString())
            //        .Aggregate((s, t) => s + " " + t));
            return A;
        }

        void shellSort(int[] A, int N) {
            int cnt = 0;
            var GList = new List<int>() {1};
            int tmp = 4;
            while(tmp < N) {
                GList.Add(tmp);
                tmp = 3 * tmp + 1;  // G_n+1 = 3 * G_n + 1
            }
            GList.Reverse();
            var G = GList.ToArray();
            int m = G.Length;

            Output(m.ToString());
            Output(G.Select(i => i.ToString())
						.Aggregate((i, j) => i + " " + j));
            for(int i = 0; i < m; i++) {
                A = selectionSort(A, N, G[i], ref cnt);
            }

            Output(cnt.ToString());
            for (int i = 0; i < N; i++)
                Output(A[i].ToString());
        }
	}
}

