class Sort
  def initialize(f)
    @cnt=0
    @n=f.length
    @a = Array.new(@n,0)
    0.upto(@n).each{|i| @a[i] = f[i]}
  end

  def insertionSort(g)
    g.upto(@n-1){|i|
      v = @a[i]
      j = i - g
      while j >= 0 and @a[j] > v do
        @a[j+g] = @a[j]
        j = j - g
        @cnt +=1
        @a[j+g] = v
      end
    }
  end

