class Sort
  def initialize(f)
    @cnt=0
    @n=f.length
    @a = Array.new(@n,0)
    0.upto(@n).each{|i| @a[i] = f[i]}
  end

  def insertionSort(g)
    g.upto(@n-1){|i|
      v = @a[i]
      j = i - g
      while j >= 0 and @a[j] > v do
        @a[j+g] = @a[j]
        j = j - g
        @cnt +=1
        @a[j+g] = v
      end
    }
  end

  def shellSort()
    m = (Math.log(2*@n+1) / Math.log(3)).to_i
    gx = Array.new(m,0)
    1.upto(m){|i| gx[i-1] = (3**i - 1)/2 }
    g = gx.reverse

#    g = [121, 40, 13, 4, 1]
#    m = g.length
    puts m
    puts g.map{|x| x.to_s}.join(" ")

    0.upto(m-1) {|i|
      insertionSort(g[i])
    }
    puts @cnt
    @a
  end

end

