void  insertionSort(std::vector<int> &a, const int n, const int g){
    for (auto i = g; i < n; ++i){
        auto v = a.at(i);
        auto j = i - g;
        while (j >= 0 and a.at(j) > v){
            a.at(j + g) = a.at(j);
            j -= g;
            ++cnt;
        }
        a.at(j + g) = v;
    }
