func insertionSort(a []int, n int, g int) ([]int, int) {
    cnt := 0
    for i := g; i < n; i++ {
        v := a[i]
        j := i -g
        for j >= 0 && a[j] > v {
            a[j+g] = a[j]
            j = j - g
            cnt++
        }
        a[j+g] = v
    }
    return a, cnt
}

func shellSort(a []int, n int) ([]int, []int, int) {
    cnt, tmp := 0, 0
    var g []int
    for h := 1; h <= n; h = 3*h+1 {
        g = append(g, 0)
        copy(g[1:], g[0:])
        g[0] = h
    }
    for i := 0; i < len(g); i++ {
        a, tmp = insertionSort(a, n, g[i])
        cnt += tmp
    }
    return a, g, cnt
}

