func insertionSort(n int, as []int, g int, count *int) {
	for i := 0; i < n-g; i++ {
		for j := i + g; j > g-1; j = j - g {
			if as[j] < as[j-g] {
				a := as[j]
				as[j] = as[j-g]
				as[j-g] = a
				*count = *count + 1
			} else {
				j = g - 1
			}
		}
	}
}

