func insertionSort(A []int, n, g int) ([]int, int) {
	cnt := 0
	for i := g; i < n; i++ {
		v := A[i]
		j := i - g
		for j >= 0 && A[j] > v {
			A[j+g] = A[j]
			j = j - g
			cnt++
		}
		A[j+g] = v
	}
	return A, cnt
}

func shellSort(A []int, n int) ([]int, []int, int) {
	cnt, tmp := 0, 0
	var G []int
	for h := 1; h <= n; {
		G = append(G, h)
		h = 3*h + 1
	}
	sort.Sort(sort.Reverse(sort.IntSlice(G)))
