func main() {

	// 繰り返し回数
	N, _ := strconv.Atoi(readLine())

	//words := strings.Fields(readLine())

	intWords := make([]int, 0)
	for i := 0; i < N; {
		intWord, _ := strconv.Atoi(readLine())
		intWords = append(intWords, intWord)
		i++
	}

	//fmt.Println(reduce(intWords))

	// スパン
	span_g := getspan(N)

	fmt.Println(len(span_g))
	fmt.Println(reduce(span_g))

	cnt := 0

	for _, g := range span_g {

		/**
		選択そーと
		 */
		for index := 0; index < N; {

			// ソート済みエリアで入れ替え
			for indexInSorted := index; indexInSorted - g >= 0; {
				if intWords[indexInSorted-g] > intWords[indexInSorted] {
					// 交換
					temp := intWords[indexInSorted-g]
					intWords[indexInSorted-g] = intWords[indexInSorted]
					intWords[indexInSorted] = temp

					// カウント
					cnt++
				}
				indexInSorted -= g
			}

			// 1ずつ増やしていく。
			index++
		}
	}

	fmt.Println(cnt)

	for _, value := range intWords {
		fmt.Println(value)
	}
	return
}

var rdr = bufio.NewReaderSize(os.Stdin, 1000000)

func readLine() string {
	buf := make([]byte, 0, 1000000)
	for {
		l, p, e := rdr.ReadLine()
		if e != nil {
			panic(e)
		}
		buf = append(buf, l...)
		if !p {
			break
		}
	}
	return string(buf)
}

func reduce(numArray []int) string {
	reducedString := ""
	for _, num := range numArray {
		reducedString += " " + strconv.FormatInt(int64(num), 10)
	}
	return strings.Trim(reducedString, " ")
}

func getspan(N int) []int {
	var spans []int

	for span := 1; span <= N; {

		spans = append([]int{span}, spans...)
		span = 3*span + 1
	}

	return spans
}

