func shellSort(a []int, n int) (int, []int) {

	m, g := calcInterval(n)

	for _, v := range g {
		insertSort(a, n, v)
	}
	return m, g
}

func calcInterval(n int) (int, []int) {
	rg := []int{}
	m := 0
	for v := 1; v <= n; v = 3*v + 1 {
		m++
		rg = append(rg, v)
	}
	g := []int{}
	for i := len(rg) - 1; i >= 0; i-- {
		g = append(g, rg[i])
	}
	return m, g
}

func insertSort(a []int, n, g int) {
	for i := g; i < n; i++ {
		v := a[i]
		j := i - g
		for j >= 0 && a[j] > v {
			a[j+g] = a[j]
			j = j - g
			cnt++
		}
		a[j+g] = v
	}
}

