	is := []int{}
	for stdin.Scan() {
		i := scanInt(stdin)
		is = append(is, i)
	}
	return is
}

func scanInt(sc *bufio.Scanner) int {
	t := sc.Text()
	i, err := strconv.Atoi(t)
