func insertionSort(aa []int, n, g int) int {
	cnt := 0
	for i := g; i < n; i++ {
		v := aa[i]
		j := i - g
		for j >= 0 && aa[j] > v {
			aa[j+g] = aa[j]
			j -= g
			cnt++
		}
		aa[j+g] = v
	}

	return cnt
}

func shellSort(aa []int, n int) (int, []int) {
	cnt := 0
	gg := make([]int, 0)
	for g := 1; g <= n; g = 3*g + 1 {
		gg = append(gg, g)
	}
	l := len(gg)
	for i := 0; i*2 < l; i++ {
		gg[i], gg[l-1-i] = gg[l-1-i], gg[i]
	}
	for i := 0; i < l; i++ {
		cnt += insertionSort(aa, n, gg[i])
	}

	return cnt, gg
}

