func shellSort(a []int, n int) {
	//https://ja.wikipedia.org/wiki/%E3%82%B7%E3%82%A7%E3%83%AB%E3%82%BD%E3%83%BC%E3%83%88#cite_note-Knuth-5
	g := []int{}

	i := 1
	for {
		tmp := (intPow(3, i) - 1) / 2
		if tmp > n {
			break
		}
		g = append(g, tmp)
		i++
	}
	fmt.Println(len(g))

	for i := len(g) - 1; i >= 0; i-- {
		fmt.Print(g[i])
		insertionSort(a, n, g[i])
		if i > 0 {
			fmt.Print(" ")
		} else {
			fmt.Println()
		}
	}
}

func insertionSort(a []int, n, g int) {
	//g=iの時通常のinsertionSort
	for i := g; i < n; i++ {
		v := a[i]
		j := i - g
		for j >= 0 && a[j] > v {
			a[j+g] = a[j]
			j = j - g
			cnt++
		}
		a[j+g] = v
	}
}

func intPow(b, x int) int {
	p := 1
	for i := 0; i < x; i++ {
		p *= b
	}
	return p
}

