func isorts(a []int, g int) (mv int) {
	// fmt.Printf("isorts(a %v, g %v) en:\n", a, g)
	n := len(a)
	for i := g; i < n; i++ { // 一定距離g離れたところから開始する
		v := a[i]
		j := i - g
		// fmt.Println("g", g, "i", i, "start", "a", a, "v", v)
		for j >= 0 && a[j] > v {
			a[j+g] = a[j]
			j = j - g
			mv++
		}
		a[j+g] = v
		// fmt.Println("g", g, "i", i, "done ", "a", a)
	}
	// fmt.Printf("isorts(a %v, g %v) ex:\n", a, g)
	return
}

func shellsort(a, G []int) (ret int) {
	for i := 0; i < len(G); i++ {
		ret += isorts(a, G[i])
	}
	return
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	n := nextInt(sc)
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt(sc)
	}
	G := make([]int, 0)
	gn := 1 // g(n+1) = 3*g(n)+1 を利用する
	// G = append(G, gn)
	for i := 0; gn <= n; i++ {
		G = append(G, gn)
		gn = 3*gn + 1
	}
	sort.Sort(sort.Reverse(sort.IntSlice(G)))
	cnt := shellsort(a, G)

	wtr := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(wtr, len(G)) // m
	for i := 0; i < len(G); i++ {
		if i > 0 {
			fmt.Fprint(wtr, " ")
		}
		fmt.Fprint(wtr, G[i])
	}
	fmt.Fprintln(wtr)
	fmt.Fprintln(wtr, cnt)
	for i := 0; i < len(a); i++ {
		fmt.Fprintln(wtr, a[i])
	}
	wtr.Flush()
}
