var rdr = bufio.NewReaderSize(os.Stdin, 1000000)

func readLine() string {
	buf := make([]byte, 0, 1000000)
	for {
		l, p, e := rdr.ReadLine()
		if e != nil {
			panic(e)
		}
		buf = append(buf, l...)
		if !p {
			break
		}
	}
	return string(buf)
}

func reduce(numArray []int) string {
	reducedString := ""
	for _, num := range numArray {
		reducedString += " " + strconv.FormatInt(int64(num), 10)
	}
	return strings.Trim(reducedString, " ")
}

func getspan(N int) []int {
	var spans []int

	for span := 1; span <= N; {

		spans = append([]int{span}, spans...)
		span = 3*span + 1
	}

	return spans
}

