func insertionSort(a ints, g int) {

	// ソート済みエリアが右に進んでいくイメージ
	// 最初はa[0]だけがソート済みと考える．
	// a[i]で対象要素を選び，ソート済みエリアのどこに
	// 挿入できるか探す

	for i := g; i < len(a); i++ {
		for j := i; j-g >= 0; j -= g {
			if a[j-g] <= a[j] {
				// ソート済み
				break
			}
			v := a[j]
			a[j] = a[j-g]
			a[j-g] = v
		}
	}
}

