type Result struct {
	elems []int
	count int
}

func calcG(length int) ([]int, error) {
	if length <= 0 {
		err := fmt.Errorf("illegal length: %d\n", length)
		return nil, err
	}
	n := length - 1
	g := []int{}
	for n > 1 {
		g = append(g, n)
		n = n / 2
	}
	g = append(g, 1)
	return g, nil
}

func insertionSort(elems []int, g int) Result {
	n := len(elems)
	count := 0
	for i := g - 1; i < n; i++ {
		v := elems[i]
		vi := i
		for j := i - g; j >= 0; j = j - g {
			if elems[j] > v {
				elems[j+g] = elems[j]
				vi = j
				count++
			} else {
				break
			}
		}
		elems[vi] = v
	}
	return Result{elems, count}
}

func shellSort(elems []int) (Result, []int) {
	g, _ := calcG(len(elems))
	count := 0
	for _, v := range g {
		result := insertionSort(elems, v)
		count += result.count
		elems = result.elems
	}
	return Result{elems, count}, g
}

