def shell(l):
	N = len(l)
	cnt = 0
	if N <= 4:
		m = 1
	elif N <= 40:
		m = 2
	else:
		m = 5
	G = [(3 ** i - 1) // 2 for i in range(m, 0, -1)]

	for i in range(m):
		l, cnt = insert(l, G[i], cnt)

	return l, m, G, cnt

def insert(l, g, cnt):
	N = len(l)

	for i in range(g, N):
		v = l[i]
		j = i - g

		while j >= 0 and l[j] > v:
			l[j + g] = l[j]
			j -= g
			cnt += 1

		l[j + g] = v

	return l, cnt

