        v = A[i]
        j = i - g
        while (j >= 0) and (A[j] > v):
            A[j + g] = A[j]
            j -= g
            cnt += 1
        A[j + g] = v
    return A, cnt

def shell_sort(A):
    cnt = 0
    G = sorted([3*i + 1 for i in range(len(A)) if 3*i+1 < len(A)], reverse=True)
    for g in G:
        A, c = insertion_sort_for_shell(A, g)
        cnt += c
    return A, G, cnt


