    let mut A = (0..N).map(|_| buf_it.next().unwrap().parse::<isize>().unwrap()).collect::<Vec<_>>();

    let mut G = Vec::new();
    let mut k = N/2;
    while k>0{
        G.push(k);
        k /= 2;
    }
    G.push(1);
    let m = G.len();

    let cnt = shellSort(&mut A,&G,N);

    println!("{}",m);
