    for &a in &A{
        println!("{}",a);
    }
}

fn shellSort(A:&mut Vec<isize>,G:&Vec<usize>,N:usize)->usize{
    let mut cnt = 0;
    for &g in G{
        cnt += insertionSort(A,N,g);
    }
    cnt
}

fn insertionSort(A:&mut Vec<isize>,N:usize,g:usize)->usize{
    let mut cnt = 0;
    for i in g..N{
        let v = A[i];
        let mut j = (i-g) as isize;
        while j >= 0 && A[j as usize]>v{
            A[j as usize +g] = A[j as usize];
            cnt += 1;
            j = j - g as isize;
        }
        A[(j+g as isize) as usize] = v;
    }
    cnt
}

