fn insertion_sort(target_array: &mut Vec<i32>, n: i32, g: i32) -> i32 {
    let mut cnt = 0;

    for i in 0..n {
        let v = target_array[i as usize];
        let mut j = i - g;

        while j >= 0 && target_array[j as usize] > v {
            target_array[(j + g) as usize] = target_array[j as usize];
            j = j - g;
            cnt += 1;
        }

        target_array[(j + g) as usize] = v
    }

    cnt
}

