    } else {
        let mut h = 1;
        while h < n {
            g.push(h);
            h = 3 * h + 1;
        }
        g.reverse()
    }
    let m = g.len();

    for i in 0..m {
        let new_cnt = insertion_sort(target_array, n, g[i as usize]);
        cnt += new_cnt;
