#[derive(Debug)]
struct Quiz {
    n: usize,    // 1 <= n <= 1,000,000
    v: Vec<u32>, // 0 <= v[i] <= 10^9, length=N
}

#[derive(Debug)]
struct Answer {
    m: usize,
    g: Vec<usize>,
    cnt: u32,
    v: Vec<u32>,
}

impl Input {
    fn into_quiz(mut self) -> Quiz {
        let n: usize = self.parse_next().unwrap();
        let v: Vec<u32> = self.parse_next_vec(n).unwrap();
        Quiz { n, v }
    }
}

impl Quiz {
    fn solve(self) -> Answer {
        let f = |i| (3usize.pow(i) -1) /2;
        let mut gs = Vec::new();
        let mut i = 1;
        let mut gi = f(i);
        while gi < self.n {
            gs.push( gi );
            i += 1;
            gi = f(i);
        }
        gs.reverse();
        if gs.len() <= 0 { // UGH 
            gs.push( 1 );
        }
        let m = gs.len();
        dprintln!("gs: {:?}", gs);

        let (v, cnt) = Quiz::shell_sort(&self.v, self.v.len(), &gs, m);

        Answer {
            m : m,
            g : gs,
            cnt : cnt,
            v : v,
        }
    }

    fn shell_sort(v: &Vec<u32>, length: usize, gs: &Vec<usize>, m: usize) -> (Vec<u32>, u32) {
        let mut cnt = 0;

        let mut vv = v.to_vec();
        for i in 0usize..(m as usize) {
            let (v_i, cnt_i) = Quiz::insertion_sort(&vv, length, gs[i]);
            vv = v_i;
            cnt += cnt_i;
        }

        (vv, cnt)
    }

    fn insertion_sort(v: &Vec<u32>, length: usize, g: usize) -> (Vec<u32>, u32) {
        let mut cnt = 0;
        let mut v = v.to_vec();
        let length = length;

        dprintln!("insertion_sort by g={}", g);

        let mut i = g;
        while i < length {
            let key = v[i].clone();
            dprintln!(" v:{:?}", v);
            dprintln!(" i {}, v[{}] = {}", i, i, key);
            let mut j: i32 = (i - g) as i32;
            while j >= 0 && v[j as usize] > key {
                dprintln!("  v[{}] > key, swap", j);
                let jj = j as usize; // j>=0
                v[jj + g] = v[jj];
                j = j - g as i32;
                cnt += 1;
            }
            let j_plus_g = (j + g as i32) as usize;
            dprintln!("  v[{}] <- {}", j_plus_g, key);
            dprintln!("    swap_cnt {}", cnt);
            v[j_plus_g] = key;
            i += 1; 
        }

        dprintln!(" result v: {:?}, cnt:{}", v, cnt);

        (v, cnt)
    }
}

impl Answer {
    fn print(self) {
        println!("{}", self.m);
        println!("{}", concat_vec_to_string(&self.g));
        println!("{}", self.cnt);
        for e in self.v {
            println!("{}", e);
        }
    }
}

