// Utility Functions
pub fn concat_vec_to_string<T>(v: &Vec<T>) -> String
where
    T: std::fmt::Display,
{
    let mut string = String::new();

    if let Some((h, t)) = v.split_first() {
        string = h.to_string();

        for obj in t {
            string = format!("{} {}", string, obj);
        }
    }

    return string;
}

