    for i in g..n {
        let mut v = a[i as usize];
        let mut j: i32 = i as i32 - g as i32;
        while j >= 0 && a[j as usize] > v {
            a[(j + g as i32) as usize] = a[j as usize];
            j = j - g as i32;
            cnt += 1;
        }
        a[(j + g as i32) as usize] = v;
    }
    cnt
}

