    let mut cnt = 0;

    let mut d = 2;
    let mut g: Vec<u32> = vec![];
    while d <= n {
        g.push(n / d);
        d *= 2;
    }
    if g.len() == 0 {
        g.push(1);
    }

    for i in 0..g.len() {
        cnt = cnt + insertion_sort(a, n, g[i]);
    }

    println!("{}", g.len());

    let mut s: Vec<String> = vec![];
    for v in g {
        s.push(v.to_string());
    }
    println!("{}", s.join(" "));
    println!("{}", cnt);

    for v in a {
